                            nativePaths.add(nativePath.isEmpty()||nativePath.length()>=240?"":nativePath+"/"+index);
                            nativeParents.add(limited(string(node.getClassName()),96));
                        }else if(background!=null)throw new StaleObservation("后台子树已变化，需重新观察");
                    }
