            public ObservedChildText.Metadata metadata(AccessibilityNodeInfo node){
                if(refreshChildren&&node!=root&&!node.refresh()){
                    staleChild[0]=true;throw new StaleObservation("后台标签子节点已不可用，需重新观察");
                }
