            // Keep the complete readable action trace, including labels and typed text.
            if(visibleTextLimit>0){visibleTextLimit--;continue;}
            if(nodeCount>requiredIds.size()){nodeCount--;continue;}
            throw new IllegalStateException("完整任务事实与当前可操作目标超过本地上下文上限，请拆分任务");
        }
    }
    /** Keep current screen and its task evidence together after the full history. */
    private static String promptSections(JSONObject data)throws Exception{
        StringBuilder out=new StringBuilder("{\n");int included=0;
        String[] sections=data.has("task_phase")
                ?new String[]{"action_schema","task_authorization","background_session","fixed_intent_tools","apps","open_allowed_packages","apps_omitted","app_search",
                    "blocked_action","blocked","format_correction","events","last_model_decision","last_transition","screen","completion","task_phase","calculator_input"}
                :new String[]{"action_schema","task_authorization","task_phase","completion","background_session","fixed_intent_tools","apps","open_allowed_packages","apps_omitted","app_search",
                    "blocked_action","blocked","format_correction","events","last_model_decision","last_transition","screen","calculator_input"};
        for(String key:sections){
            if(!data.has(key))continue;
            if(included++>0)out.append(",\n");
            String section=new JSONObject().put(key,data.get(key)).toString();
            out.append(section,1,section.length()-1);
        }
        if(included!=data.length())throw new IllegalStateException("unrecognized prompt section");
        return out.append("\n}").toString();
    }
    private static ObservedTransitionProjection.Transition observedTransition(int step,PhoneObservation before,PhoneObservation after){
        return ObservedTransitionProjection.between(step,transitionSnapshot(before),transitionSnapshot(after));
    }
    private static ObservedTransitionProjection.Snapshot transitionSnapshot(PhoneObservation observation){
        java.util.List<ObservedTransitionProjection.Field> fields=new java.util.ArrayList<ObservedTransitionProjection.Field>();
        for(PhoneObservation.Node node:observation.nodes){
            ObservedTransitionProjection.Field field=ObservedTransitionProjection.field(observation.packageName,node.packageName,
                    node.id,node.viewId,node.text,node.editable,node.password);
            if(field!=null)fields.add(field);
        }
        return ObservedTransitionProjection.snapshot(observation.id,observation.packageName,observation.nodesTruncated,
                observation.windowMetadata.promptTitle(),observation.windowMetadata.promptTitleTruncated(),
                observation.state.imeVisibility.value(),fields);
    }
    private static java.util.Map<String,Object> historyFields(JSONObject entry)throws Exception{
        java.util.Map<String,Object> fields=new java.util.LinkedHashMap<String,Object>();
        for(java.util.Iterator<String> keys=entry.keys();keys.hasNext();){String key=keys.next();fields.put(key,entry.isNull(key)?null:entry.get(key));}
        return fields;
    }
    private static int nodeScore(PhoneObservation.Node node,String owner){
        int score=(node.clickable?4:0)+(node.editable?5:0)+(node.scrollable?2:0)+(node.enabled?1:-20);
        if(node.password)return -100;
        String label=node.label();
        if(!label.isEmpty()&&owner.contains(label))score+=20;
        if(label.length()<=4&&!label.isEmpty())score+=3;
        return score;
    }
    private static JSONObject searchMetadata(AppCatalogueRanker.Page page,int shown)throws Exception{
        int next=page.nextOffset(shown);
        return new JSONObject().put("query",page.query).put("offset",page.offset).put("matches",page.matchingApps)
                .put("total_apps",page.totalApps).put("next_offset",next<0?JSONObject.NULL:Integer.valueOf(next));
    }
    private static JSONObject searchMetadata(AppCatalogueRanker.Page page,int shown,java.util.List<java.util.Map<String,Object>> history)throws Exception{
        JSONObject result=searchMetadata(page,shown);
        java.util.Map<String,Object> provenance=RecentActionProjection.discoveryProvenance(history,page.query,page.offset,page.catalogueSha256);
        for(java.util.Map.Entry<String,Object> entry:provenance.entrySet())
            result.put(entry.getKey(),entry.getValue()==null?JSONObject.NULL:entry.getValue());
        if(Boolean.TRUE.equals(provenance.get("model_issued"))){
            int returned=((Integer)provenance.get("returned")).intValue();
            if(returned!=page.apps.size()||shown>returned)throw new IllegalStateException("本机查询结果来源不一致");
            result.put("returned_shown",shown).put("returned_omitted",returned-shown);
        }
        return result;
    }
    private static JSONObject catalogueJson(AppCatalogueRanker.Page page)throws Exception{
        JSONArray rows=new JSONArray();for(AppCatalogueRanker.Entry app:page.apps)rows.put(new JSONObject().put("package",app.packageName).put("label",app.label));
        return new JSONObject().put("schema","hepta.local-app-discovery.v1").put("source",AppCatalogueRanker.SOURCE)
                .put("catalogue_sha256",page.catalogueSha256).put("query",page.query).put("offset",page.offset)
                .put("total_apps",page.totalApps).put("matching_apps",page.matchingApps).put("apps",rows)
                .put("returned",page.apps.size()).put("prompt_may_show_fewer",true);
    }
    private static String answerJson(ActionDecision a)throws Exception{
        JSONObject value=new JSONObject().put("action",a.action).put("observation_id",a.observationId);
        if(a.appLabel!=null)value.put("app_label",a.appLabel);
        value.put("package",a.packageName);
        if(a.nodeId!=null)value.put("node_label",a.nodeLabel).put("node_id",a.nodeId);if(a.x>=0){value.put("x",a.x);value.put("y",a.y);}
        if(a.text!=null)value.put("text",a.text);if(a.direction!=null)value.put("direction",a.direction);if(a.durationMs>=0)value.put("duration_ms",a.durationMs);
        if(a.query!=null)value.put("query",a.query);if(a.offset>=0)value.put("offset",a.offset);
        if(a.status!=null)value.put("status",a.status);if(a.summary!=null)value.put("summary",a.summary);if(!a.reason.isEmpty())value.put("reason",a.reason);return value.toString();
    }
    private static String chineseAction(String action){switch(action){case "notes.create":return "打开本地笔记草稿";case "web.search":return "打开网页查询";case "find_app":return "搜索本机应用";case "open":return "打开应用";case "click":return "点击";case "type":return "输入文字";case "submit":return "提交查询字段";case "scroll":return "滚动";case "back":return "返回";case "home":return "回到桌面";case "wait":return "等待页面";default:return "检查完成状态";}}
    private static void privateDirectory(File directory)throws Exception{if(!directory.isDirectory()&&!directory.mkdirs())throw new IllegalStateException("无法建立任务目录");android.system.Os.chmod(directory.getPath(),0700);}
    private static void record(File directory,String name,JSONObject value)throws Exception{
        File file=new File(directory,name);if(!file.createNewFile())throw new IllegalStateException("证据文件标识重复");
        try(FileOutputStream stream=new FileOutputStream(file)){stream.write(value.toString(2).getBytes(StandardCharsets.UTF_8));stream.getFD().sync();}
        android.system.Os.chmod(file.getPath(),0600);
    }
}

package org.trillionnium.hepta.local;

import org.json.JSONArray;
import org.json.JSONObject;
import org.trillionnium.hepta.local.web.WebShoppingGoal;
import org.trillionnium.hepta.webprotocol.WebSitePolicy;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Bounded read-only projection of an actual complete DOM-v4 record.
 * No Mi CSS selector, SKU, price, or currency is invented from a search index.
 * Only explicit visible HTML Product/Offer semantics can produce detail data;
 * a page without those semantics remains partial until its actual layout is reviewed.
 * This projection alone cannot grant an AX action or task completion.
 */
final class MiPublicProductPage {
    static final String SCHEMA="hepta.mi-public-product-page.v2";
    static final String DOM_SCHEMA="hepta.fixed-top-document-dom.v4";
    private static final Pattern MODEL=Pattern.compile("^(?:(?:Xiaomi|小米)[ ]*(?:(?:路由器|Router)[ ]*)?)?AX3000T(?: 白色)?$",Pattern.CASE_INSENSITIVE);
    private static final Pattern AMOUNT=Pattern.compile("^(?:(?:人民币|CNY|RMB|¥|￥)[ ]*)?((?:0|[1-9][0-9]{0,7})(?:\\.[0-9]{1,2})?)(?:[ ]*元)?$");
    private static final Pattern CONDITIONAL=Pattern.compile("券|会员|补贴|定金|分期|每月|月供|预售|预约|满减|到手|折后|需登录|需领|秒杀|限时|首购");
    final String url,phase;
    final boolean modalPresent;
    final List<Link> productLinks;
    final Detail detail;
    final List<String> missing;
    private final Map<String,JSONObject> nodes;
    private final Map<String,Integer> ids;
    static final class Link {
        final String path,id,label,hrefRaw,hrefResolved,target,modelPath;
        final List<String> visibleTexts;
        Link(JSONObject node,JSONObject model,List<String> texts,String resolved)throws Exception {
            path=text(node,"path");id=text(node,"id");label=text(model,"text");
            hrefRaw=text(node,"href_raw");hrefResolved=resolved;target=text(node,"link_target");
            modelPath=text(model,"path");visibleTexts=Collections.unmodifiableList(new ArrayList<String>(texts));
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("anchor_dom_path",path);out.put("anchor_dom_id",id);
            out.put("model_dom_path",modelPath);out.put("model_label",label);out.put("href_raw",hrefRaw);
            out.put("href_resolved",hrefResolved);out.put("link_target",target);out.put("visible_texts",visibleTexts);
            out.put("navigation_authorized",false);out.put("product_detail_verified",false);return out;
        }
    }
    static final class Detail {
        final String productPath,offerPath,modelPath,modelLabel,pricePath,priceRaw,currencyPath,currencyRaw;
        final String amountDecimal,priceKind,skuPath,skuRaw;
        final List<String> visibleProductTexts,visibleOfferTexts;
        final boolean exactPublicPrice;
        Detail(String product,String offer,JSONObject model,JSONObject price,JSONObject currency,
               JSONObject sku,List<String> productTexts,List<String> offerTexts,String amount,String kind)throws Exception {
            productPath=product;offerPath=offer;modelPath=text(model,"path");modelLabel=text(model,"text");
            pricePath=text(price,"path");priceRaw=text(price,"text");currencyPath=text(currency,"path");currencyRaw=text(currency,"text");
            skuPath=sku==null?null:text(sku,"path");skuRaw=sku==null?null:text(sku,"text");
            amountDecimal=amount;priceKind=kind;exactPublicPrice="public_exact_display".equals(kind);
            visibleProductTexts=Collections.unmodifiableList(new ArrayList<String>(productTexts));
            visibleOfferTexts=Collections.unmodifiableList(new ArrayList<String>(offerTexts));
        }
        Map<String,Object> evidence(){
            Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("product_dom_path",productPath);out.put("offer_dom_path",offerPath);
            out.put("model_dom_path",modelPath);out.put("model_raw",modelLabel);out.put("price_dom_path",pricePath);
            out.put("displayed_price_raw",priceRaw);out.put("amount_decimal",amountDecimal);out.put("currency_dom_path",currencyPath);
            out.put("currency_raw",currencyRaw);out.put("currency","CNY");out.put("price_kind",priceKind);
            out.put("sku_dom_path",skuPath);out.put("visible_sku_raw",skuRaw);out.put("selected_variant",null);out.put("quantity",null);
            out.put("visible_product_texts",visibleProductTexts);out.put("visible_offer_texts",visibleOfferTexts);
            out.put("exact_configuration_verified",false);out.put("specifications_verified",false);
            out.put("native_visibility_verified",false);out.put("model_navigation_verified",false);
            out.put("task_completion_verified",false);return out;
        }
    }
    private MiPublicProductPage(String url,String phase,boolean modal,List<Link> links,Detail detail,List<String> missing,
                                Map<String,JSONObject> nodes,Map<String,Integer> ids){
        this.url=url;this.phase=phase;modalPresent=modal;productLinks=Collections.unmodifiableList(new ArrayList<Link>(links));
        this.detail=detail;this.missing=Collections.unmodifiableList(new ArrayList<String>(missing));this.nodes=nodes;this.ids=ids;
    }
    static MiPublicProductPage read(WebShoppingGoal goal,WebSitePolicy policy,String committed,JSONObject dom)throws Exception{
        need(goal!=null&&policy!=null&&dom!=null,"immutable goal/policy and actual DOM required");
        need(DOM_SCHEMA.equals(text(dom,"schema"))&&Boolean.FALSE.equals(dom.get("truncated"))
                &&dom.getJSONArray("truncation_reasons").length()==0,"complete exact DOM-v4 required");
        need(committed.equals(text(dom,"href"))&&policy.origin.equals(text(dom,"origin"))&&policy.allowsMainFrame(committed),
                "same approved committed product route required");
        need("complete".equals(text(dom,"ready_state")),"public page still loading");
        JSONArray rows=dom.getJSONArray("nodes");need(rows.length()>0&&rows.length()<=1536,"bounded actual DOM nodes");
        Map<String,JSONObject> nodes=new LinkedHashMap<String,JSONObject>();Map<String,Integer> ids=new HashMap<String,Integer>();
        for(int i=0;i<rows.length();i++){
            JSONObject n=rows.getJSONObject(i);String path=text(n,"path"),id=text(n,"id");
            need(path.matches("0(?:/[0-9]{1,5}){0,32}")&&!nodes.containsKey(path),"unique complete DOM ancestry");
            for(String k:Arrays.asList("tag","role","text","aria_label","item_type","item_prop","aria_hidden","aria_modal","aria_selected","aria_checked","aria_pressed"))
                text(n,k);
            for(String k:Arrays.asList("visible_in_viewport","disabled","item_scope","hidden_attr","inert_attr"))
                need(n.get(k) instanceof Boolean,"typed DOM boolean: "+k);
            for(String k:Arrays.asList("href_raw","href_resolved","link_target"))
                need(n.get(k)==JSONObject.NULL||n.get(k) instanceof String&&((String)n.get(k)).length()<=4096,"bounded anchor field");
            nodes.put(path,n);if(!id.isEmpty())ids.put(id,ids.containsKey(id)?ids.get(id)+1:1);
        }
        for(JSONObject n:nodes.values()){
            String path=text(n,"path");Object parent=n.get("parent_path");
            need("0".equals(path)?parent==JSONObject.NULL:parent instanceof String&&nodes.containsKey(parent)
                    &&path.substring(0,path.lastIndexOf('/')).equals(parent),"recorded DOM parent required");
        }
        List<String> missing=new ArrayList<String>();List<Link> links=new ArrayList<Link>();Detail detail=null;boolean modal=false;
        for(JSONObject n:nodes.values())if(visible(n,nodes)&&("dialog".equals(text(n,"tag"))
                ||"dialog".equals(text(n,"role"))||"alertdialog".equals(text(n,"role"))||"true".equals(text(n,"aria_modal"))))modal=true;
        WebSitePolicy.Route route=policy.classify(committed);
        String phase=route==WebSitePolicy.Route.INITIAL_PUBLIC_SEARCH?"official_public_search":"official_product_detail";
        if(modal)missing.add("visible_modal_or_consent_requires_stop");
        if(route==WebSitePolicy.Route.INITIAL_PUBLIC_SEARCH){
            try{
                org.trillionnium.hepta.webprotocol.WebMiActionRegion region=
                        org.trillionnium.hepta.webprotocol.WebMiActionRegion.read(dom);
                JSONObject anchor=nodes.get(region.anchorPath),model=nodes.get(region.modelPath);
                need(anchor!=null&&model!=null,"actual scoped anchor/model disappeared");
                List<String> texts=visibleTexts(nodes,region.anchorPath,64);
                need(!containsTransaction(texts),"transaction or consent labels cannot grant public product navigation");
                links.add(new Link(anchor,model,texts,region.hrefResolved));
                missing.add("native_semantic_region_bridge_required");
            }catch(Exception unavailable){
                missing.add("complete_observed_public_search_card_region_unavailable");
            }
            if(links.size()!=1)missing.add("unique_actual_AX3000T_anchor_not_observed");
            missing.add("detail_page_not_observed");
        }else{
            List<JSONObject> products=new ArrayList<JSONObject>();
            for(JSONObject n:nodes.values())if(visible(n,nodes)&&Boolean.TRUE.equals(n.get("item_scope"))
                    &&typeIs(n,"Product")&&insideMain(n,nodes))products.add(n);
            if(products.size()!=1)missing.add("unique_visible_explicit_Product_scope_missing");
            else{
                JSONObject product=products.get(0);String productPath=text(product,"path");
                List<JSONObject> models=matchingModel(nodes,productPath),offers=new ArrayList<JSONObject>();
                for(JSONObject n:nodes.values())if(descendant(productPath,text(n,"path"))&&visible(n,nodes)
                        &&Boolean.TRUE.equals(n.get("item_scope"))&&typeIs(n,"Offer")&&prop(n,"offers"))offers.add(n);
                if(models.size()!=1)missing.add("unique_same_product_model_missing");
                if(offers.size()!=1)missing.add("unique_visible_Offer_scope_missing");
                if(models.size()==1&&offers.size()==1){
                    String offerPath=text(offers.get(0),"path");
                    List<JSONObject> prices=properties(nodes,offerPath,"price"),currencies=properties(nodes,offerPath,"priceCurrency");
                    List<JSONObject> skus=properties(nodes,productPath,"sku");
                    if(prices.size()!=1||currencies.size()!=1)missing.add("unique_visible_price_and_currency_missing");
                    else{
                        JSONObject price=prices.get(0),currency=currencies.get(0);Matcher amount=AMOUNT.matcher(text(price,"text"));
                        boolean cny=Arrays.asList("CNY","RMB","人民币","元").contains(text(currency,"text"));
                        if(!amount.matches()||!cny||struck(price,nodes))missing.add("visible_current_CNY_amount_not_verified");
                        else{
                            BigDecimal number=new BigDecimal(amount.group(1));need(number.signum()>0,"nonpositive public price");
                            List<String> productTexts=visibleTexts(nodes,productPath,256),offerTexts=visibleTexts(nodes,offerPath,96);
                            String joined=join(productTexts);String kind=CONDITIONAL.matcher(joined).find()?"conditional":
                                    joined.contains("起")?"starting_price":"public_exact_display";
                            detail=new Detail(productPath,offerPath,models.get(0),price,currency,skus.size()==1?skus.get(0):null,
                                    productTexts,offerTexts,amount.group(1),kind);
                            if(!detail.exactPublicPrice)missing.add("price_is_starting_or_conditional");
                            if(goal.singleUnitRequested)missing.add("requested_single_unit_and_selected_variant_unverified");
                            if(goal.specificationsRequested)missing.add("requested_hardware_specifications_unverified");
                        }
                    }
                }
            }
        }
        return new MiPublicProductPage(committed,phase,modal,links,detail,missing,nodes,ids);
    }
    Map<String,Object> evidence(){
        Map<String,Object> out=new LinkedHashMap<String,Object>();out.put("schema",SCHEMA);out.put("current_native_url",url);
        out.put("phase",phase);out.put("visible_modal_present",modalPresent);List<Object> links=new ArrayList<Object>();
        for(Link link:productLinks)links.add(link.evidence());out.put("actual_product_link_candidates",links);
        out.put("detail_projection",detail==null?null:detail.evidence());out.put("missing",missing);
        out.put("search_index_used",false);out.put("price_or_SKU_filled_from_goal",false);out.put("business_verified",false);
        out.put("layout_visibility_is_screen_proof",false);return out;
    }
    boolean uniqueId(String id){return id!=null&&!id.isEmpty()&&Integer.valueOf(1).equals(ids.get(id));}
    private static List<JSONObject> matchingModel(Map<String,JSONObject> nodes,String root)throws Exception{
        List<JSONObject> out=new ArrayList<JSONObject>();for(JSONObject n:nodes.values())
            if(descendant(root,text(n,"path"))&&visible(n,nodes)&&MODEL.matcher(text(n,"text")).matches())out.add(n);return out;
    }
    private static List<JSONObject> properties(Map<String,JSONObject> nodes,String root,String property)throws Exception{
        List<JSONObject> out=new ArrayList<JSONObject>();for(JSONObject n:nodes.values())
            if(descendant(root,text(n,"path"))&&visible(n,nodes)&&prop(n,property)&&!text(n,"text").isEmpty())out.add(n);return out;
    }
    private static List<String> visibleTexts(Map<String,JSONObject> nodes,String root,int max)throws Exception{
        List<String> out=new ArrayList<String>();for(JSONObject n:nodes.values())if(descendant(root,text(n,"path"))&&visible(n,nodes)){
            String s=text(n,"text");if(!s.isEmpty()){need(out.size()<max,"complete product text budget exceeded");out.add(s);}}
        return out;
    }
    private static boolean nestedControl(Map<String,JSONObject> nodes,String root)throws Exception{
        for(JSONObject n:nodes.values()){String path=text(n,"path");if(path.equals(root)||!descendant(root,path))continue;
            if(Arrays.asList("a","button","input","select","textarea").contains(text(n,"tag"))
                    ||Arrays.asList("button","checkbox","radio","textbox").contains(text(n,"role")))return true;}
        return false;
    }
    private static boolean containsTransaction(List<String> texts){String s=join(texts);
        return s.contains("购买")||s.contains("加购")||s.contains("购物车")||s.contains("付款")||s.contains("支付")
                ||s.contains("领券")||s.contains("登录")||s.contains("同意")||s.contains("下单");}
    private static boolean insideMain(JSONObject node,Map<String,JSONObject> nodes)throws Exception{
        JSONObject n=node;while(n!=null){if("main".equals(text(n,"tag"))||"main".equals(text(n,"role")))return true;
            Object p=n.get("parent_path");n=p instanceof String?nodes.get(p):null;}return false;
    }
    private static boolean struck(JSONObject node,Map<String,JSONObject> nodes)throws Exception{
        JSONObject n=node;while(n!=null){if("del".equals(text(n,"tag"))||"s".equals(text(n,"tag")))return true;
            Object p=n.get("parent_path");n=p instanceof String?nodes.get(p):null;}return false;
    }
    private static boolean typeIs(JSONObject n,String type)throws Exception{
        String value=text(n,"item_type");return value.equals("https://schema.org/"+type)||value.equals("http://schema.org/"+type);
    }
    private static boolean prop(JSONObject n,String value)throws Exception{return Arrays.asList(text(n,"item_prop").split("\\s+")).contains(value);}
    private static boolean visible(JSONObject node,Map<String,JSONObject> nodes)throws Exception{
        JSONObject n=node;while(n!=null){
            if(!Boolean.TRUE.equals(n.get("visible_in_viewport"))||Boolean.TRUE.equals(n.get("hidden_attr"))
                    ||Boolean.TRUE.equals(n.get("inert_attr"))||"true".equals(text(n,"aria_hidden")))return false;
            Object p=n.get("parent_path");if(p==JSONObject.NULL)return "0".equals(text(n,"path"));n=nodes.get(p);
        }return false;
    }
    private static String join(List<String> strings){StringBuilder out=new StringBuilder();for(String s:strings)out.append(s).append('\n');return out.toString();}
    private static boolean descendant(String root,String path){return root.equals(path)||path.startsWith(root+"/");}
    private static String text(JSONObject value,String key)throws Exception{
        Object raw=value.get(key);need(raw instanceof String&&((String)raw).length()<=4096,"bounded actual DOM string: "+key);
        return (String)raw;
    }
    private static void need(boolean ok,String why){if(!ok)throw new IllegalArgumentException(why);}
}

package org.trillionnium.hepta.local;

import android.graphics.Rect;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import java.io.File;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Immutable description of one observed active window and original-size screenshot. */
public final class PhoneObservation {
    /** Counters from the real bounded traversal, never inferred from a flat
     * archived node list. Legacy observations have no counters. These describe
     * collection limits; they do not supply node actions or business evidence. */
    public static final class CollectionStats {
        public static final String SCHEMA="hepta.observation-collection.v1";
        public final int visitLimit,nodeLimit,textLimit,visited,retained,textUtf16,pending,
                nodeBudgetOmissions,textBudgetOmissions;
        public final long childSlotsOmitted,elapsedMs;
        public final List<String> limitReasons;
        CollectionStats(int visitLimit,int nodeLimit,int textLimit,int visited,int retained,int textUtf16,
                        int pending,int nodeBudgetOmissions,int textBudgetOmissions,long childSlotsOmitted,long elapsedMs){
            if(visitLimit<=0||nodeLimit<=0||textLimit<=0||visited<0||visited>visitLimit
                    ||retained<0||retained>nodeLimit||textUtf16<0||textUtf16>=textLimit
                    ||pending<0||pending>visitLimit||nodeBudgetOmissions<0||textBudgetOmissions<0
                    ||childSlotsOmitted<0||elapsedMs<0)throw new IllegalArgumentException("invalid actual collection counters");
            this.visitLimit=visitLimit;this.nodeLimit=nodeLimit;this.textLimit=textLimit;
            this.visited=visited;this.retained=retained;this.textUtf16=textUtf16;this.pending=pending;
            this.nodeBudgetOmissions=nodeBudgetOmissions;this.textBudgetOmissions=textBudgetOmissions;
            this.childSlotsOmitted=childSlotsOmitted;this.elapsedMs=elapsedMs;
            List<String> reasons=new ArrayList<String>();
            if(childSlotsOmitted>0||pending>0)reasons.add("traversal_limit");
            if(nodeBudgetOmissions>0)reasons.add("node_limit");
            if(textBudgetOmissions>0)reasons.add("text_limit");
            limitReasons=Collections.unmodifiableList(reasons);
        }
        public boolean truncated(){return !limitReasons.isEmpty();}
        JSONObject json()throws JSONException{
            return new JSONObject().put("schema",SCHEMA).put("source","same_observed_accessibility_traversal")
                    .put("visit_limit",visitLimit).put("node_limit",nodeLimit).put("text_utf16_exclusive_limit",textLimit)
                    .put("visited_nodes",visited).put("retained_nodes",retained).put("retained_text_utf16",textUtf16)
                    .put("pending_nodes_at_stop",pending).put("child_slots_omitted_by_traversal_limit",childSlotsOmitted)
                    .put("nodes_omitted_by_node_limit",nodeBudgetOmissions).put("nodes_omitted_by_text_limit",textBudgetOmissions)
                    .put("truncation_reasons",new JSONArray(limitReasons)).put("elapsed_ms",elapsedMs)
                    .put("unvisited_descendant_count_known",false).put("grants_action_capability",false);
        }
    }
    public static final class Node {
        public final String id, packageName, className, viewId, text, description;
        public final ObservedChildText.Result childText;
        public final ObservedScrollActions scrollActions;
        public final ObservedImeEnter imeEnter;
        public final String inputTextSha256;
        /** Actual NodeRef signature, never reconstructed from serialized labels. */
        public final String observedAppTreeSignature;
        /** Position recorded by the same native traversal; legacy/omitted positions remain null. */
        public final String nativeTreePath,nativeParentClass;
        public final boolean submitAvailable;
        public final Rect bounds;
        public final boolean clickable, editable, scrollable, enabled, focused, password;
        Node(String id, String packageName, String className, String viewId, String text,
             String description, Rect bounds, boolean clickable, boolean editable,
             boolean scrollable, boolean enabled, boolean focused, boolean password,ObservedChildText.Result childText,
             ObservedScrollActions scrollActions) {
            this(id,packageName,className,viewId,text,description,bounds,clickable,editable,scrollable,enabled,focused,password,
                    childText,scrollActions,ObservedImeEnter.UNKNOWN,null,false);
        }
        Node(String id, String packageName, String className, String viewId, String text,
             String description, Rect bounds, boolean clickable, boolean editable,
             boolean scrollable, boolean enabled, boolean focused, boolean password,ObservedChildText.Result childText,
             ObservedScrollActions scrollActions,ObservedImeEnter imeEnter,String inputTextSha256,boolean submitAvailable) {
            this(id,packageName,className,viewId,text,description,bounds,clickable,editable,scrollable,enabled,focused,password,
                    childText,scrollActions,imeEnter,inputTextSha256,submitAvailable,null);
        }
        Node(String id, String packageName, String className, String viewId, String text,
             String description, Rect bounds, boolean clickable, boolean editable,
             boolean scrollable, boolean enabled, boolean focused, boolean password,ObservedChildText.Result childText,
             ObservedScrollActions scrollActions,ObservedImeEnter imeEnter,String inputTextSha256,boolean submitAvailable,String observedAppTreeSignature) {
            this(id,packageName,className,viewId,text,description,bounds,clickable,editable,scrollable,enabled,focused,password,
                    childText,scrollActions,imeEnter,inputTextSha256,submitAvailable,observedAppTreeSignature,null,null);
        }
        Node(String id, String packageName, String className, String viewId, String text,
             String description, Rect bounds, boolean clickable, boolean editable,
             boolean scrollable, boolean enabled, boolean focused, boolean password,ObservedChildText.Result childText,
             ObservedScrollActions scrollActions,ObservedImeEnter imeEnter,String inputTextSha256,boolean submitAvailable,
             String observedAppTreeSignature,String nativeTreePath,String nativeParentClass) {
            if(nativeTreePath==null){
                if(nativeParentClass!=null)throw new IllegalArgumentException("native parent without an actual traversal path");
            }else if(nativeParentClass==null||nativeParentClass.length()>96
                    ||!nativeTreePath.matches("0(?:/(?:0|[1-9][0-9]{0,5})){0,127}"))
                throw new IllegalArgumentException("invalid bounded actual native traversal path");
            this.nativeTreePath=nativeTreePath;this.nativeParentClass=nativeParentClass;
            this.id=id; this.packageName=packageName; this.className=className; this.viewId=viewId;
            this.text=text; this.description=description; this.bounds=new Rect(bounds);
            this.childText=childText;
            if(observedAppTreeSignature!=null&&!ObservedImeEnter.isSha(observedAppTreeSignature))
                throw new IllegalArgumentException("actual node signature must be a SHA-256 value");
            this.observedAppTreeSignature=observedAppTreeSignature;
            if(scrollActions==null)throw new IllegalArgumentException("observed scroll action state required");
            this.scrollActions=scrollActions;
            if(imeEnter==null)throw new IllegalArgumentException("observed IME action state required");
            if(submitAvailable&&(!editable||!focused||!enabled||password||!imeEnter.queryAllowed()||!ObservedImeEnter.isSha(inputTextSha256)))
                throw new IllegalArgumentException("submit capability lacks observed field facts");
            this.imeEnter=imeEnter;this.inputTextSha256=inputTextSha256;this.submitAvailable=submitAvailable;
            this.clickable=clickable; this.editable=editable; this.scrollable=scrollable;
            this.enabled=enabled; this.focused=focused; this.password=password;
        }
        public String label(){return ObservedChildText.displayLabel(text,description,childText);}
        JSONObject json() throws JSONException {
            JSONObject value=new JSONObject();
            value.put("id",id); value.put("bounds",new JSONArray(new int[]{bounds.left,bounds.top,bounds.right,bounds.bottom}));
            value.put("package",packageName).put("class_name",className);
            if (!text.isEmpty()) value.put("text",text);
            if (!description.isEmpty()) value.put("description",description);
            if (!"not_applicable".equals(childText.status)) {
                value.put("child_text_status",childText.status).put("child_text_truncated",childText.truncated)
                        .put("child_text_sources_complete",childText.sourcesComplete).put("child_text_visited",childText.visited);
                if(!childText.text.isEmpty()) {
                    value.put("child_text",childText.text).put("child_text_source",ObservedChildText.SOURCE)
                            .put("child_text_root_signature",childText.rootSignature);
                    JSONArray sources=new JSONArray();for(ObservedChildText.Source source:childText.sources)
                        sources.put(new JSONObject().put("descendant_path",source.descendantPath).put("property",source.property)
                                .put("text_sha256",source.textSha256).put("node_signature",source.nodeSignature).put("view_id",source.viewId));
                    value.put("child_text_sources",sources);
                }
            }
            if (!viewId.isEmpty()) value.put("view_id",viewId);
            if(observedAppTreeSignature!=null)value.put("node_app_tree_sha256",observedAppTreeSignature);
            if(nativeTreePath!=null)value.put("native_tree_position",new JSONObject()
                    .put("schema","hepta.native-tree-position.v1").put("path",nativeTreePath)
                    .put("parent_class",nativeParentClass).put("source","same_bounded_accessibility_traversal")
                    .put("grants_action_capability",false));
            if (clickable) value.put("clickable",true);
            if (editable) value.put("editable",true);
            if (scrollable) value.put("scrollable",true); // Platform isScrollable, not a direction grant.
            value.put("scroll_actions_observed",scrollActions.observed);
            value.put("scroll_directions",scrollActions.observed?new JSONArray(scrollActions.directions):JSONObject.NULL);
            value.put("input_text_sha256",inputTextSha256==null?JSONObject.NULL:inputTextSha256);
            value.put("ime_enter",new JSONObject(imeEnter.evidence())).put("submit_available",submitAvailable);
            if (!enabled) value.put("enabled",false);
            if (focused) value.put("focused",true);
            if (password) value.put("password",true);
            return value;
        }
    }
