package org.trillionnium.hepta.webprotocol;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.regex.Pattern;
import org.json.JSONArray;
import org.json.JSONObject;

/**
 * One fixed, observed mainland-Mi search-card region. This is not a selector
 * supplied by a webpage/model, a detail-price result, or transaction authority.
 * Native AX identity/window/lease and native dispatch remain independent gates.
 */
public final class WebMiActionRegion {
    public static final String OBS_SCHEMA="hepta.mi-search-card-observations.v1";
    public static final String SCHEMA="hepta.mi-public-search-card-region.v1";
    public static final String SELECTION="fixed_AX3000T_white_observed_link_parent_card_v1";
    public static final String POLICY="mi_cn_ax3000t_read_v2";
    private static final String TITLE="Xiaomi路由器AX3000T 白色";
    private static final Pattern PRICE=Pattern.compile("^(?:0|[1-9][0-9]{0,7})(?:\\.[0-9]{1,2})?元$");
    private static final Pattern CONDITION=Pattern.compile("券|会员|补贴|定金|分期|每月|月供|预售|预约|满减|到手|折后|需登录|需领|秒杀|限时|首购|加入购物车|立即购买|下单|支付");
    public final String rootPath,anchorPath,modelPath,currentPricePath,comparisonPricePath;
    public final String hrefRaw,hrefResolved,linkTarget,modelLabel,observedVariant;
    public final String currentPriceRaw,comparisonPriceRaw,currentAmountDecimal,comparisonAmountDecimal;
    public final String fullRegionSha256,ancestorSha256,observationsSha256;
    private final String immutableEvidence;
    private final Set<String> regionPaths,ancestorPaths;
    private final double[] regionRect;
    private WebMiActionRegion(JSONObject candidate,JSONArray region,JSONArray ancestors,JSONObject observations,
                              Set<String> regionSet,Set<String> ancestorSet,double[] bounds)throws Exception{
        rootPath=text(candidate,"root_path");anchorPath=text(candidate,"anchor_path");modelPath=text(candidate,"model_path");
        currentPricePath=text(candidate,"current_price_path");comparisonPricePath=text(candidate,"comparison_price_path");
        hrefRaw=text(candidate,"href_raw");hrefResolved=text(candidate,"href_resolved");linkTarget=text(candidate,"link_target");
        modelLabel=text(candidate,"model_label");observedVariant=text(candidate,"observed_variant");
        currentPriceRaw=text(candidate,"current_price_raw");comparisonPriceRaw=text(candidate,"comparison_price_raw");
        currentAmountDecimal=amount(currentPriceRaw);comparisonAmountDecimal=amount(comparisonPriceRaw);
        fullRegionSha256=WebDomCanonical.sha256(region);ancestorSha256=WebDomCanonical.sha256(ancestors);
        observationsSha256=WebDomCanonical.sha256(observations);
        regionPaths=Collections.unmodifiableSet(new LinkedHashSet<String>(regionSet));
        ancestorPaths=Collections.unmodifiableSet(new LinkedHashSet<String>(ancestorSet));regionRect=bounds.clone();
        JSONObject evidence=new JSONObject().put("schema",SCHEMA).put("selection",SELECTION).put("site_policy_id",POLICY)
                .put("candidate",new JSONObject(WebDomCanonical.canonical(candidate)))
                .put("full_region_node_count",region.length()).put("full_region_sha256",fullRegionSha256)
                .put("ancestor_node_count",ancestors.length()).put("ancestor_sha256",ancestorSha256)
                .put("observations_sha256",observationsSha256).put("region_rect_css_pixels",new JSONArray(bounds))
                .put("observed_current_price_amount",currentAmountDecimal)
                .put("observed_comparison_price_amount",comparisonAmountDecimal).put("observed_currency","CNY")
                .put("current_price_context","search_card_only").put("comparison_price_context","del_descendant")
                .put("observed_top_document_hit_clear",true).put("top_document_rect_overlap_check",true)
                .put("native_ax_identity_verified",false).put("native_dispatch_verified",false)
                .put("closed_shadow_contents_inspected",false).put("whole_page_pixel_visibility_verified",false)
                .put("fully_unoccluded_claimed",false).put("detail_price_verified",false)
                .put("grants_action_authority",false).put("business_verified",false);
        immutableEvidence=WebDomCanonical.canonical(evidence);
    }
    public JSONObject evidence()throws Exception{return new JSONObject(immutableEvidence);}
    public boolean containsPath(String path){return regionPaths.contains(path);}
    public boolean isAncestorPath(String path){return ancestorPaths.contains(path);}
    /** Only the actual anchor is an action target, never a cart or region ancestor. */
    public boolean permitsActionTargetPath(String path){return anchorPath.equals(path)&&regionPaths.contains(path);}
    public boolean overlaps(double[] rect){return overlap(regionRect,rect);}
    public boolean sameRegion(WebMiActionRegion other)throws Exception{
        return other!=null&&immutableEvidence.equals(other.immutableEvidence);
    }
    public static WebMiActionRegion read(JSONObject dom)throws Exception{return read(dom,WebDomStability.index(dom));}
    static WebMiActionRegion read(JSONObject dom,Map<String,JSONObject> nodes)throws Exception{
        need(WebSitePolicy.INITIAL_URL.equals(text(dom,"href"))&&WebSitePolicy.ORIGIN.equals(text(dom,"origin")),
                "fixed observed Mi public search page required");
        JSONObject observations=dom.getJSONObject("action_region_observations");
        need(OBS_SCHEMA.equals(text(observations,"schema"))&&POLICY.equals(text(observations,"site_policy_id"))
                &&SELECTION.equals(text(observations,"selection"))&&"observed".equals(text(observations,"status"))
                &&integer(observations,"candidate_count")==1&&bool(observations,"complete")
                &&!bool(observations,"coordinates_used_for_input")&&!bool(observations,"closed_shadow_contents_inspected")
                &&!bool(observations,"pixel_visibility_claimed"),"complete fixed read-only region observations required");
        List<JSONObject> candidates=new ArrayList<JSONObject>();WebSitePolicy policy=WebSitePolicy.forExplicitDiagnostic();
        for(JSONObject anchor:nodes.values()){
            if(!"a".equals(text(anchor,"tag"))||!visible(anchor))continue;
            String path=text(anchor,"path"),parent=parent(path);
            if(parent==null||!nodes.containsKey(parent)||!"div".equals(text(nodes.get(parent),"tag")))continue;
            String raw=nullable(anchor,"href_raw"),resolved=nullable(anchor,"href_resolved"),target=nullable(anchor,"link_target");
            if(policy.observedProductLink(WebSitePolicy.INITIAL_URL,raw,resolved,target)==null)continue;
            List<JSONObject> models=new ArrayList<JSONObject>(),current=new ArrayList<JSONObject>(),comparison=new ArrayList<JSONObject>();
            int links=0,count=0;boolean forbidden=false;
            for(JSONObject node:nodes.values()){
                String npath=text(node,"path");if(!inside(parent,npath))continue;
                count++;String tag=text(node,"tag");
                if("a".equals(tag))links++;
                if(oneOf(tag,"button","input","select","textarea","iframe","frame","object","embed","canvas","video","svg")
                        ||"button".equals(text(node,"role"))||"dialog".equals(text(node,"role"))||"true".equals(text(node,"aria_modal")))forbidden=true;
                if(!visible(node))continue;
                String label=text(node,"text");
                if(CONDITION.matcher(label).find())forbidden=true;
                if(inside(path,npath)&&"h2".equals(tag)&&TITLE.equals(label))models.add(node);
                if(inside(path,npath)&&"span".equals(tag)&&PRICE.matcher(label.trim()).matches())
                    (underDeleted(npath,path,nodes)?comparison:current).add(node);
            }
            if(forbidden||count<4||count>64||links!=1||models.size()!=1||current.size()!=1||comparison.size()!=1)continue;
            candidates.add(new JSONObject().put("root_path",parent).put("anchor_path",path).put("model_path",text(models.get(0),"path"))
                    .put("current_price_path",text(current.get(0),"path")).put("comparison_price_path",text(comparison.get(0),"path"))
                    .put("model_label",TITLE).put("observed_variant","白色").put("href_raw",raw).put("href_resolved",resolved)
                    .put("link_target",target).put("current_price_raw",text(current.get(0),"text"))
                    .put("comparison_price_raw",text(comparison.get(0),"text")).put("price_context","search_card_only")
                    .put("detail_price_verified",false));
        }
        need(candidates.size()==1&&WebDomCanonical.same(candidates.get(0),observations.getJSONObject("candidate")),
                "unique complete fixed product card must independently match the observer");
        JSONObject candidate=candidates.get(0);String root=text(candidate,"root_path"),anchor=text(candidate,"anchor_path");
        JSONObject rootNode=nodes.get(root);double[] bounds=WebDomStability.rect(rootNode.getJSONArray("rect_css_pixels"));
        need(visible(rootNode)&&WebDomCanonical.same(rootNode.getJSONArray("rect_css_pixels"),nodes.get(anchor).getJSONArray("rect_css_pixels")),
                "observed complete card and its sole anchor rectangle must coincide");
        JSONArray viewport=dom.getJSONArray("viewport_css_pixels");need(viewport.length()==2,"actual viewport required");
        double width=number(viewport.get(0)),height=number(viewport.get(1));
        need(bounds[2]>bounds[0]&&bounds[3]>bounds[1]&&bounds[0]>=0&&bounds[1]>=0&&bounds[2]<=width&&bounds[3]<=height,
                "complete current card must be inside the observed CSS viewport");
        Set<String> regionSet=new LinkedHashSet<String>(),ancestorSet=new LinkedHashSet<String>();
        JSONArray region=new JSONArray(),ancestors=new JSONArray();
        List<String> foreign=new ArrayList<String>(),modals=new ArrayList<String>(),special=new ArrayList<String>();
        for(JSONObject node:nodes.values()){
            String path=text(node,"path");boolean member=inside(root,path),ancestor=!member&&inside(path,root);
            if(member){regionSet.add(path);region.put(node);}
            if(ancestor){ancestorSet.add(path);ancestors.put(node);}
            if((member||ancestor)&&(bool(node,"hidden_attr")||bool(node,"inert_attr")||bool(node,"disabled")
                    ||"true".equals(text(node,"aria_hidden"))))throw new IllegalArgumentException("region or ancestor explicitly hidden/inert/disabled");
            if(!visible(node))continue;
            if(oneOf(text(node,"tag"),"dialog")||oneOf(text(node,"role"),"dialog","alertdialog")||"true".equals(text(node,"aria_modal")))modals.add(path);
            if(overlap(bounds,WebDomStability.rect(node.getJSONArray("rect_css_pixels")))){
                if(!member&&!ancestor)foreign.add(path);
                if(member&&oneOf(text(node,"tag"),"iframe","frame","object","embed","canvas","video","svg"))special.add(path);
            }
        }
        need(equalList(foreign,observations.getJSONArray("foreign_overlap_paths"))&&foreign.isEmpty()
                &&equalList(modals,observations.getJSONArray("visible_modal_paths"))&&modals.isEmpty()
                &&equalList(special,observations.getJSONArray("special_paint_in_region_paths"))&&special.isEmpty(),
                "observed foreign overlap/modal/special paint blocks the action region");
        JSONObject top=observations.getJSONObject("top_layer");
        need(bool(top,"selector_api_available")&&top.getJSONArray("modal_paths").length()==0
                &&top.getJSONArray("popover_paths").length()==0&&!bool(top,"fullscreen_present")
                &&top.get("fullscreen_path")==JSONObject.NULL&&!bool(top,"closed_shadow_contents_inspected"),
                "observed top-layer activity or incomplete selector support blocks the region");
        Map<String,JSONObject> styles=new LinkedHashMap<String,JSONObject>();
        JSONArray contexts=observations.getJSONArray("style_contexts");need(contexts.length()<=128,"bounded region CSS context");
        Set<String> expected=new LinkedHashSet<String>(ancestorSet);expected.addAll(regionSet);
        for(int i=0;i<contexts.length();i++){
            JSONObject style=contexts.getJSONObject(i);String path=text(style,"path");
            need(expected.contains(path)&&!styles.containsKey(path),"unique real region CSS path");
            for(String key:new String[]{"position","display","visibility","opacity","overflow_x","overflow_y","overflow_clip_margin",
                    "transform","translate","rotate","scale","transform_style","zoom","perspective","filter","backdrop_filter",
                    "clip_path","mask_image","contain","content_visibility","will_change","pointer_events","isolation","mix_blend_mode"})text(style,key);
            need(!bool(style,"accessible_shadow_root_present")&&!bool(style,"closed_shadow_contents_inspected"),
                    "open shadow context is outside this top-document region schema");
            need(integer(style,"element_child_count")>=0,"observed element children required");
            // A hit can remain clickable under an opacity-zero ancestor. Read
            // all observed region/ancestor styles; hit testing is not paint proof.
            need(!"none".equals(text(style,"display"))&&"visible".equals(text(style,"visibility"))
                    &&finiteText(text(style,"opacity"))==1d&&"visible".equals(text(style,"content_visibility"))
                    &&"none".equals(text(style,"filter"))&&"none".equals(text(style,"backdrop_filter"))
                    &&"none".equals(text(style,"clip_path"))&&"none".equals(text(style,"mask_image"))
                    &&"normal".equals(text(style,"mix_blend_mode")),
                    "observed region/ancestor visibility or unsupported paint effect blocks reading");
            rejectObservedPseudoOverlay(style.getJSONObject("pseudo_before"));
            rejectObservedPseudoOverlay(style.getJSONObject("pseudo_after"));
            styles.put(path,style);
        }
        need(styles.keySet().equals(expected),"all region nodes and real ancestors require CSS observations");
        for(String p:new String[]{root,anchor,text(candidate,"model_path"),text(candidate,"current_price_path"),text(candidate,"comparison_price_path")}){
            JSONObject style=styles.get(p);
            need(visible(nodes.get(p))&&!"none".equals(text(style,"display"))&&"visible".equals(text(style,"visibility"))
                    &&finiteText(text(style,"opacity"))>0&&"visible".equals(text(style,"content_visibility")),
                    "actual label/anchor display state is not readable");
        }
        JSONArray tests=observations.getJSONArray("hit_tests");
        List<String> testPaths=Arrays.asList(anchor,text(candidate,"model_path"),text(candidate,"current_price_path"),text(candidate,"comparison_price_path"));
        need(tests.length()==testPaths.size(),"all fixed region hit observations required");
        double[][] ratios={{.5,.5},{.2,.2},{.8,.2},{.2,.8},{.8,.8}};
        for(int i=0;i<tests.length();i++){
            JSONObject test=tests.getJSONObject(i);String path=testPaths.get(i);
            need(path.equals(text(test,"dom_path"))&&WebDomCanonical.same(test.getJSONArray("rect_css_pixels"),nodes.get(path).getJSONArray("rect_css_pixels")),
                    "hit observation must bind the actual node rectangle");
            double[] r=WebDomStability.rect(test.getJSONArray("rect_css_pixels"));
            need(r[0]>=bounds[0]&&r[1]>=bounds[1]&&r[2]<=bounds[2]&&r[3]<=bounds[3]&&r[2]>r[0]&&r[3]>r[1],"fixed readable point rectangle inside card");
            JSONArray points=test.getJSONArray("points");need(points.length()==ratios.length,"all fixed hit points required");
            for(int j=0;j<ratios.length;j++){
                JSONObject point=points.getJSONObject(j);double x=number(point.get("x")),y=number(point.get("y"));
                need(Math.abs(x-(r[0]+(r[2]-r[0])*ratios[j][0]))<=0.000001
                        &&Math.abs(y-(r[1]+(r[3]-r[1])*ratios[j][1]))<=0.000001,"observed hit coordinates must be derived from fixed CSS test points");
                String hit=text(point,"top_path");JSONArray stack=point.getJSONArray("stack_paths");
                need(nodes.containsKey(hit)&&inside(anchor,hit)&&bool(point,"stack_complete")
                        &&stack.length()>0&&stack.length()<=64&&hit.equals(stack.get(0)),"actual top-document hit is absent, retargeted or obstructed");
                for(int k=0;k<stack.length();k++)need(stack.get(k) instanceof String&&nodes.containsKey(stack.getString(k)),"complete real DOM hit-stack paths");
            }
        }
        return new WebMiActionRegion(candidate,region,ancestors,observations,regionSet,ancestorSet,bounds);
    }
    private static void rejectObservedPseudoOverlay(JSONObject pseudo)throws Exception{
        String content=text(pseudo,"content"),display=text(pseudo,"display"),visibility=text(pseudo,"visibility");
        String position=text(pseudo,"position"),transform=text(pseudo,"transform");text(pseudo,"pointer_events");
        double opacity=finiteText(text(pseudo,"opacity"));
        boolean generated=!"none".equals(content)&&!"normal".equals(content)&&!"none".equals(display)
                &&!"hidden".equals(visibility)&&!"collapse".equals(visibility)&&opacity>0;
        need(!generated||(!oneOf(position,"absolute","fixed","sticky")&&"none".equals(transform)),
                "observed positioned/transformed generated content makes region occlusion unknown");
    }
    private static boolean underDeleted(String path,String stop,Map<String,JSONObject> nodes)throws Exception{
        for(String p=path;p!=null&&!p.equals(stop);p=parent(p))if("del".equals(text(nodes.get(p),"tag")))return true;return false;
    }
    private static boolean visible(JSONObject node)throws Exception{
        return node!=null&&bool(node,"visible_in_viewport")&&!bool(node,"hidden_attr")&&!bool(node,"inert_attr")
                &&!bool(node,"disabled")&&!"true".equals(text(node,"aria_hidden"));
    }
    private static boolean equalList(List<String> list,JSONArray actual)throws Exception{
        if(list.size()!=actual.length())return false;for(int i=0;i<list.size();i++)if(!list.get(i).equals(actual.get(i)))return false;return true;
    }
    private static String amount(String raw){String s=raw.trim();need(PRICE.matcher(s).matches(),"explicit CNY search-card amount required");return new BigDecimal(s.substring(0,s.length()-1)).stripTrailingZeros().toPlainString();}
    private static boolean inside(String root,String path){return path.equals(root)||path.startsWith(root+"/");}
    private static boolean overlap(double[] a,double[] b){return Math.max(a[0],b[0])<Math.min(a[2],b[2])&&Math.max(a[1],b[1])<Math.min(a[3],b[3]);}
    private static String parent(String path){int p=path.lastIndexOf('/');return p<0?null:path.substring(0,p);}
    private static boolean oneOf(String value,String... options){for(String option:options)if(option.equals(value))return true;return false;}
    private static String nullable(JSONObject object,String key)throws Exception{Object value=object.get(key);return value==JSONObject.NULL?null:text(object,key);}
    private static String text(JSONObject object,String key)throws Exception{
        Object value=object.get(key);need(value instanceof String&&((String)value).length()<=4096,"bounded raw string: "+key);return (String)value;
    }
    private static boolean bool(JSONObject object,String key)throws Exception{Object value=object.get(key);need(value instanceof Boolean,"typed boolean: "+key);return (Boolean)value;}
    private static long integer(JSONObject object,String key)throws Exception{Object value=object.get(key);need(value instanceof Integer||value instanceof Long,"integer: "+key);return ((Number)value).longValue();}
    private static double number(Object value){need(value instanceof Number,"observed number required");double n=((Number)value).doubleValue();need(Double.isFinite(n)&&Math.abs(n)<=9007199254740991d,"finite observed number required");return n;}
    private static double finiteText(String text){double value=Double.parseDouble(text);need(Double.isFinite(value),"finite CSS scalar");return value;}
    private static void need(boolean value,String message){if(!value)throw new IllegalArgumentException(message);}
}

package org.trillionnium.hepta.webprotocol;

import org.json.JSONObject;

/**
 * Typed one-shot link arm derived from the helper's last successful fresh capture.
 * A request supplies identities/hashes/path, never a URL or page script.
 * An ARM receipt is not a click, navigation completion, or business result.
 */
public final class WebObservedNavigation {
    public static final String ARM_SCHEMA="hepta.web-helper.observed-link-arm.v1";
    public static final String NAV_SCHEMA="hepta.web-helper.observed-link-navigation.v1";
    public static final String CAPTURE_SCHEMA="hepta.owned-webview-origin-dom.v2";
    public static final long SOURCE_MAX_AGE_MS=2500,ARM_BUDGET_MS=1500;
    private WebObservedNavigation(){}
    public static void requireRequest(JSONObject request)throws Exception{
        java.util.Set<String> keys=new java.util.TreeSet<String>();
        java.util.Iterator<String> it=request.keys();while(it.hasNext())keys.add(it.next());
        need(keys.equals(WebEvidenceProtocol.requestKeys(WebEvidenceProtocol.ARM_OBSERVED_LINK))
                &&WebEvidenceProtocol.requestSchema(WebEvidenceProtocol.ARM_OBSERVED_LINK).equals(text(request,"schema")),
                "exact observed-link request required");
        need(WebEvidenceProtocol.hex32(text(request,"task_id"))
                &&WebEvidenceProtocol.hex64(text(request,"controller_session_nonce"))
                &&WebEvidenceProtocol.hex64(text(request,"request_nonce"))
                &&WebEvidenceProtocol.uuid(text(request,"expected_webview_instance"))
                &&integer(request,"expected_navigation_epoch")>=0
                &&WebEvidenceProtocol.hex64(text(request,"source_capture_challenge"))
                &&WebEvidenceProtocol.hex64(text(request,"source_dom_sha256"))
                &&WebEvidenceProtocol.hex64(text(request,"source_stability_sha256"))
                &&text(request,"anchor_dom_path").matches("0(?:/[0-9]{1,5}){0,32}")
                &&WebEvidenceProtocol.hex32(text(request,"model_run_id")),
                "observed-link request identity/hash/path shape");
        need(integer(request,"deadline_elapsed_ms")>0,"positive observed-link request deadline");
    }
    public static JSONObject arm(JSONObject request,JSONObject binding,JSONObject capture,long now)throws Exception{
        requireRequest(request);WebTaskPurpose purpose=WebTaskPurpose.requireBinding(binding);
        need(purpose.shopping!=null&&WebMiActionRegion.POLICY.equals(purpose.sitePolicyId),
                "only the compiled public shopping purpose can arm a product link");
        need(text(binding,"task_id").equals(text(request,"task_id"))
                &&text(binding,"controller_session_nonce").equals(text(request,"controller_session_nonce"))
                &&WebEvidenceBinding.canonical(binding).equals(WebEvidenceBinding.canonical(capture.getJSONObject("binding"))),
                "last successful capture belongs to another lease");
        need(CAPTURE_SCHEMA.equals(text(capture,"schema"))
                &&Boolean.FALSE.equals(capture.get("business_verified"))
                &&Boolean.FALSE.equals(capture.get("truncated"))
                &&integer(capture,"display_id")>0&&integer(capture,"actual_window_id")>=0
                &&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(capture,"helper_package")),
                "current formal wire-v4 capture required");
        need(text(request,"source_capture_challenge").equals(text(capture,"challenge"))
                &&text(request,"expected_webview_instance").equals(text(capture,"webview_instance"))
                &&integer(request,"expected_navigation_epoch")==integer(capture,"navigation_epoch")
                &&text(request,"source_dom_sha256").equals(text(capture,"dom_sha256")),
                "fresh capture identity changed");
        String before=text(capture,"before_dom_raw_utf8"),after=text(capture,"dom_raw_utf8");
        WebDomStability.Result stability=WebDomStability.verify(before,after,purpose.sitePolicyId,capture.getJSONObject("dom_stability"));
        need(stability.region!=null&&stability.permitsActionTargetPath(text(request,"anchor_dom_path"))
                &&stability.afterRawSha256.equals(text(request,"source_dom_sha256"))
                &&stability.beforeRawSha256.equals(text(capture,"before_dom_sha256"))
                &&WebDomCanonical.sha256(stability.evidence()).equals(text(request,"source_stability_sha256"))
                &&WebDomCanonical.sha256(stability.evidence()).equals(text(capture,"dom_stability_sha256")),
                "only the actual stable region anchor can be armed");
        WebMiActionRegion region=stability.region;
        need("_blank".equals(region.linkTarget),"this observed-link arm handles the actual new-window card link only");
        JSONObject geometry=capture.getJSONObject("capture_geometry");
        need("hepta.webview-geometry-bracket.v2".equals(text(geometry,"schema"))
                &&geometry.getJSONArray("samples").length()==4
                &&Boolean.TRUE.equals(geometry.get("native_samples_equal"))
                &&Boolean.TRUE.equals(geometry.get("ui_thread_bracket"))
                &&stability.comparisonScope.equals(text(geometry,"dom_comparison_scope"))
                &&Boolean.valueOf(stability.rawEqual).equals(geometry.get("dom_equal_across_visual_callback")),
                "complete actual native geometry bracket is required");
        long ended=integer(capture,"ended_elapsed_ms"),started=integer(capture,"started_elapsed_ms");
        JSONObject bg=binding.getJSONObject("background");long expires=integer(bg,"expires_elapsed_ms");
        long requestDeadline=integer(request,"deadline_elapsed_ms");
        need(now>=0&&now<=Long.MAX_VALUE-ARM_BUDGET_MS&&started<=ended&&ended<=now&&now-ended<=SOURCE_MAX_AGE_MS
                &&requestDeadline>now&&requestDeadline-now<=WebEvidenceProtocol.MAX_RPC_FUTURE_MS&&requestDeadline<=expires,
                "fresh capture/arm/lease deadline invalid");
        long deadline=Math.min(Math.min(requestDeadline,expires),Math.min(now+ARM_BUDGET_MS,ended+SOURCE_MAX_AGE_MS));
        return new JSONObject().put("schema",ARM_SCHEMA).put("request_nonce",text(request,"request_nonce"))
                .put("task_id",text(request,"task_id")).put("controller_session_nonce",text(request,"controller_session_nonce"))
                .put("binding_sha256",WebEvidenceBinding.sha256(binding)).put("model_run_id",text(request,"model_run_id"))
                .put("source_capture_challenge",text(request,"source_capture_challenge"))
                .put("source_dom_sha256",stability.afterRawSha256).put("source_before_dom_sha256",stability.beforeRawSha256)
                .put("source_stability_sha256",text(request,"source_stability_sha256"))
                .put("comparison_scope",stability.comparisonScope).put("anchor_dom_path",region.anchorPath)
                .put("region_root_path",region.rootPath).put("region_sha256",region.fullRegionSha256)
                .put("observed_href_raw",region.hrefRaw).put("observed_href_resolved",region.hrefResolved)
                .put("observed_link_target",region.linkTarget).put("site_policy_id",purpose.sitePolicyId)
                .put("source_native_url",text(capture,"current_native_url"))
                .put("webview_instance",text(capture,"webview_instance")).put("navigation_epoch",integer(capture,"navigation_epoch"))
                .put("actual_window_id",integer(capture,"actual_window_id")).put("display_id",integer(capture,"display_id"))
                .put("storage_profile_name",text(binding,"storage_profile_name"))
                .put("source_capture_ended_elapsed_ms",ended).put("armed_elapsed_ms",now).put("expires_elapsed_ms",deadline)
                .put("one_shot",true).put("url_supplied_by_controller_or_model",false)
                .put("native_click_observed",false).put("navigation_dispatched",false)
                .put("new_visible_window_allowed",false).put("external_app_allowed",false)
                .put("transaction_authority",false).put("business_verified",false);
    }
    public static JSONObject verifyArm(JSONObject request,JSONObject binding,JSONObject capture,JSONObject claimed)throws Exception{
        JSONObject expected=arm(request,binding,capture,integer(claimed,"armed_elapsed_ms"));
        need(WebDomCanonical.same(expected,claimed),"observed-link ARM receipt differs from fresh capture");return expected;
    }
    /**
     * Checks the exact bounded record shape, including incomplete/cancelled records.
     * This method never confirms a click, successful navigation, or a business result.
     * Receipt consumers must retain this record and later call verifyNavigation with
     * the private verified ARM and original accepted native ActionOutcome bracket.
     */
    public static void requireNavigationRecordShape(JSONObject nav)throws Exception{
        need(nav!=null&&NAV_SCHEMA.equals(text(nav,"schema")),"typed observed navigation record required");
        exactKeys(nav,new String[]{
                "schema","arm","popup_callback_observed","popup_callback_elapsed_ms","popup_is_dialog","popup_is_user_gesture",
                "popup_url_observed","popup_url_observed_elapsed_ms","popup_observed_url","popup_observed_method","popup_observed_main_frame",
                "popup_initiating_frame_verified","auxiliary_network_loads_blocked","auxiliary_view_created","auxiliary_view_destroyed",
                "same_profile_assignment","auxiliary_destroyed_elapsed_ms","same_lease_main_load_invoked","same_lease_main_load_returned",
                "main_load_begin_elapsed_ms","main_load_returned_elapsed_ms","new_visible_window_created","external_app_launched",
                "transaction_authority","business_verified","cancelled","cancelled_elapsed_ms","cancellation_reason"});
        JSONObject arm=nav.getJSONObject("arm");
        exactKeys(arm,new String[]{"schema","request_nonce","task_id","controller_session_nonce","binding_sha256","model_run_id",
                "source_capture_challenge","source_dom_sha256","source_before_dom_sha256","source_stability_sha256","comparison_scope",
                "anchor_dom_path","region_root_path","region_sha256","observed_href_raw","observed_href_resolved","observed_link_target",
                "site_policy_id","source_native_url","webview_instance","navigation_epoch","actual_window_id","display_id",
                "storage_profile_name","source_capture_ended_elapsed_ms","armed_elapsed_ms","expires_elapsed_ms","one_shot",
                "url_supplied_by_controller_or_model","native_click_observed","navigation_dispatched","new_visible_window_allowed",
                "external_app_allowed","transaction_authority","business_verified"});
        need(ARM_SCHEMA.equals(text(arm,"schema")),"typed nested ARM required");
        for(String key:new String[]{"request_nonce","task_id","controller_session_nonce","binding_sha256","model_run_id",
                "source_capture_challenge","source_dom_sha256","source_before_dom_sha256","source_stability_sha256","comparison_scope",
                "anchor_dom_path","region_root_path","region_sha256","observed_href_raw","observed_href_resolved","observed_link_target",
                "site_policy_id","source_native_url","webview_instance","storage_profile_name"})
            need(text(arm,key).length()<=4096,"bounded nested ARM string: "+key);
        for(String key:new String[]{"navigation_epoch","actual_window_id","display_id","source_capture_ended_elapsed_ms",
                "armed_elapsed_ms","expires_elapsed_ms"})need(integer(arm,key)>=0,"nonnegative nested ARM time/identity: "+key);
        need(Boolean.TRUE.equals(arm.get("one_shot")),"one-shot ARM record required");
        for(String key:new String[]{"url_supplied_by_controller_or_model","native_click_observed","navigation_dispatched",
                "new_visible_window_allowed","external_app_allowed","transaction_authority","business_verified"})
            need(Boolean.FALSE.equals(arm.get(key)),"nested ARM must not grant or claim action: "+key);
        for(String key:new String[]{"popup_callback_observed","popup_url_observed","popup_initiating_frame_verified",
                "auxiliary_network_loads_blocked","auxiliary_view_created","auxiliary_view_destroyed",
                "same_lease_main_load_invoked","same_lease_main_load_returned","new_visible_window_created",
                "external_app_launched","transaction_authority","business_verified","cancelled"})
            need(nav.get(key) instanceof Boolean,"typed navigation flag: "+key);
        for(String key:new String[]{"popup_is_dialog","popup_is_user_gesture","popup_observed_main_frame"})
            need(nav.get(key)==JSONObject.NULL||nav.get(key) instanceof Boolean,"nullable navigation flag: "+key);
        for(String key:new String[]{"popup_callback_elapsed_ms","popup_url_observed_elapsed_ms","auxiliary_destroyed_elapsed_ms",
                "main_load_begin_elapsed_ms","main_load_returned_elapsed_ms","cancelled_elapsed_ms"})
            need(nav.get(key)==JSONObject.NULL||integer(nav,key)>=0,"nullable navigation timestamp: "+key);
        for(String key:new String[]{"popup_observed_url","popup_observed_method","cancellation_reason"})
            need(nav.get(key)==JSONObject.NULL||nav.get(key) instanceof String&&text(nav,key).length()<=4096,
                    "nullable bounded navigation string: "+key);
        for(String key:new String[]{"popup_initiating_frame_verified","new_visible_window_created",
                "external_app_launched","transaction_authority","business_verified"})
            need(Boolean.FALSE.equals(nav.get(key)),"unsupported navigation claim: "+key);
        Object profile=nav.get("same_profile_assignment");
        if(profile!=JSONObject.NULL){
            need(profile instanceof JSONObject,"nullable profile assignment object required");
            JSONObject assigned=(JSONObject)profile;
            exactKeys(assigned,new String[]{"profile_assignment_api","profile_assigned_before_other_interactions","actual_profile_name",
                    "profile_assigned_elapsed_ms","reused_same_lease_profile","network_loads_blocked","javascript_enabled","visible_in_layout"});
            need(text(assigned,"profile_assignment_api").length()<=128&&text(assigned,"actual_profile_name").length()<=128
                    &&integer(assigned,"profile_assigned_elapsed_ms")>=0,"bounded actual profile assignment");
            for(String key:new String[]{"profile_assigned_before_other_interactions","reused_same_lease_profile",
                    "network_loads_blocked","javascript_enabled","visible_in_layout"})
                need(assigned.get(key) instanceof Boolean,"typed profile assignment flag: "+key);
        }
        need(WebDomCanonical.canonical(nav).getBytes(java.nio.charset.StandardCharsets.UTF_8).length<=65536,
                "bounded observed navigation record");
    }
    private static void exactKeys(JSONObject value,String[] expected)throws Exception{
        java.util.Set<String> actual=new java.util.TreeSet<String>();java.util.Iterator<String> it=value.keys();
        while(it.hasNext())actual.add(it.next());
        need(actual.equals(new java.util.TreeSet<String>(java.util.Arrays.asList(expected))),"exact observed record keys");
    }
    /**
     * Replays the helper's observed popup and same-lease load against an actual
     * native dispatch time bracket. The caller still independently requires the
     * original accepted/dispatched/not-stale ActionOutcome and current receipt.
     */
    public static JSONObject verifyNavigation(JSONObject expectedArm,JSONObject nav,JSONObject destination,
                                             long dispatchStarted,long dispatchEnded)throws Exception{
        requireNavigationRecordShape(nav);
        need(nav!=null&&NAV_SCHEMA.equals(text(nav,"schema"))&&ARM_SCHEMA.equals(text(expectedArm,"schema"))
                &&WebDomCanonical.same(expectedArm,nav.getJSONObject("arm")),"same actual ARM/navigation required");
        java.util.Set<String> expectedKeys=new java.util.TreeSet<String>(java.util.Arrays.asList(
                "schema","arm","popup_callback_observed","popup_callback_elapsed_ms","popup_is_dialog","popup_is_user_gesture",
                "popup_url_observed","popup_url_observed_elapsed_ms","popup_observed_url","popup_observed_method","popup_observed_main_frame",
                "popup_initiating_frame_verified","auxiliary_network_loads_blocked","auxiliary_view_created","auxiliary_view_destroyed",
                "same_profile_assignment","auxiliary_destroyed_elapsed_ms","same_lease_main_load_invoked","same_lease_main_load_returned",
                "main_load_begin_elapsed_ms","main_load_returned_elapsed_ms","new_visible_window_created","external_app_launched",
                "transaction_authority","business_verified","cancelled","cancelled_elapsed_ms","cancellation_reason"));
        java.util.Set<String> actualKeys=new java.util.TreeSet<String>();java.util.Iterator<String> keys=nav.keys();
        while(keys.hasNext())actualKeys.add(keys.next());need(actualKeys.equals(expectedKeys),"complete typed observed navigation fields");
        for(String key:new String[]{"popup_callback_observed","popup_is_user_gesture","popup_url_observed","popup_observed_main_frame",
                "auxiliary_network_loads_blocked","auxiliary_view_created","auxiliary_view_destroyed",
                "same_lease_main_load_invoked","same_lease_main_load_returned"})
            need(Boolean.TRUE.equals(nav.get(key)),"actual positive navigation fact required: "+key);
        for(String key:new String[]{"popup_is_dialog","popup_initiating_frame_verified","new_visible_window_created",
                "external_app_launched","transaction_authority","business_verified","cancelled"})
            need(Boolean.FALSE.equals(nav.get(key)),"navigation scope differs: "+key);
        need(nav.get("cancelled_elapsed_ms")==JSONObject.NULL&&nav.get("cancellation_reason")==JSONObject.NULL,
                "cancelled or partially completed navigation cannot be confirmed");
        String href=text(expectedArm,"observed_href_resolved"),profile=text(expectedArm,"storage_profile_name");
        need("_blank".equals(text(expectedArm,"observed_link_target"))&&href.equals(text(nav,"popup_observed_url"))
                &&"GET".equals(text(nav,"popup_observed_method")),"actual popup target/method differs from observed card");
        JSONObject assigned=nav.getJSONObject("same_profile_assignment");
        need(profile.equals(text(assigned,"actual_profile_name"))
                &&"WebViewCompat.setProfile".equals(text(assigned,"profile_assignment_api"))
                &&Boolean.TRUE.equals(assigned.get("profile_assigned_before_other_interactions"))
                &&Boolean.TRUE.equals(assigned.get("reused_same_lease_profile"))
                &&Boolean.TRUE.equals(assigned.get("network_loads_blocked"))
                &&Boolean.FALSE.equals(assigned.get("javascript_enabled"))
                &&Boolean.FALSE.equals(assigned.get("visible_in_layout")),"actual URL interceptor profile/network facts differ");
        long armed=integer(expectedArm,"armed_elapsed_ms"),deadline=integer(expectedArm,"expires_elapsed_ms");
        long popup=integer(nav,"popup_callback_elapsed_ms"),assign=integer(assigned,"profile_assigned_elapsed_ms"),
                requested=integer(nav,"popup_url_observed_elapsed_ms"),destroyed=integer(nav,"auxiliary_destroyed_elapsed_ms"),
                invoked=integer(nav,"main_load_begin_elapsed_ms"),returned=integer(nav,"main_load_returned_elapsed_ms");
        need(armed<=dispatchStarted&&dispatchStarted<=dispatchEnded&&dispatchEnded<=deadline
                &&dispatchStarted<=popup&&popup<=assign&&assign<=requested&&requested<=destroyed&&destroyed<=invoked
                &&invoked<=returned&&returned<deadline,"actual dispatch/popup/profile/destruction/load time chain differs");
        need(CAPTURE_SCHEMA.equals(text(destination,"schema"))&&Boolean.FALSE.equals(destination.get("business_verified"))
                &&Boolean.FALSE.equals(destination.get("truncated"))
                &&text(expectedArm,"binding_sha256").equals(WebEvidenceBinding.sha256(destination.getJSONObject("binding")))
                &&profile.equals(text(destination.getJSONObject("binding"),"storage_profile_name"))
                &&text(expectedArm,"webview_instance").equals(text(destination,"webview_instance"))
                &&integer(expectedArm,"actual_window_id")==integer(destination,"actual_window_id")
                &&integer(expectedArm,"display_id")==integer(destination,"display_id")
                &&integer(destination,"navigation_epoch")>integer(expectedArm,"navigation_epoch")
                &&href.equals(text(destination,"current_native_url"))&&href.equals(text(destination,"committed_main_frame_url"))
                &&returned<=integer(destination,"started_elapsed_ms")
                &&integer(destination,"started_elapsed_ms")<=integer(destination,"ended_elapsed_ms"),
                "actual destination capture does not follow the same-lease observed navigation");
        WebTaskPurpose purpose=WebTaskPurpose.requireBinding(destination.getJSONObject("binding"));
        need(purpose.shopping!=null&&WebSitePolicy.forShopping(purpose.shopping).classify(href)==WebSitePolicy.Route.PUBLIC_DETAIL_CANDIDATE,
                "actual destination is outside the fixed public detail policy");
        WebDomStability.Result stable=WebDomStability.verify(text(destination,"before_dom_raw_utf8"),
                text(destination,"dom_raw_utf8"),purpose.sitePolicyId,destination.getJSONObject("dom_stability"));
        need(stable.rawEqual&&stable.region==null,"current detail capture is whole raw stable and grants no click target");
        return new JSONObject().put("schema","hepta.web-helper.observed-navigation-verdict.v1")
                .put("arm_request_nonce",text(expectedArm,"request_nonce")).put("model_run_id",text(expectedArm,"model_run_id"))
                .put("source_capture_challenge",text(expectedArm,"source_capture_challenge"))
                .put("destination_capture_challenge",text(destination,"challenge")).put("observed_href",href)
                .put("helper_navigation_chain_verified",true).put("native_action_outcome_verified_by_this_method",false)
                .put("same_lease_profile",profile).put("detail_price_verified",false).put("business_verified",false);
    }
    public static long integer(JSONObject o,String key)throws Exception{
        Object v=o.get(key);need(v instanceof Integer||v instanceof Long,"integer "+key+" required");return ((Number)v).longValue();
    }
    public static String text(JSONObject o,String key)throws Exception{Object v=o.get(key);need(v instanceof String,"string "+key+" required");return (String)v;}
    private static void need(boolean value,String reason){if(!value)throw new IllegalArgumentException(reason);}
}

package org.trillionnium.hepta.webprotocol;

import org.json.JSONArray;
import org.json.JSONObject;
import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

/** Pure replay of native Android observations. A caller assertion is not an OS observation. */
public final class WebRecoveryPolicy {
    private WebRecoveryPolicy() { }
    public static final String PROBE_SCHEMA="hepta.web-helper.retirement-probe.v1";
    public static final String DECISION_SCHEMA="hepta.web-helper.retirement-decision.v1";
    public static final int MAX_DISPLAYS=64,MAX_EXIT_RECORDS=32;
    public static final long MAX_PROBE_MS=3000;
    public static JSONObject evaluate(JSONObject prior,JSONObject observed)throws Exception{
        JSONObject answer=new JSONObject().put("schema",DECISION_SCHEMA).put("verified",false)
                .put("kind",JSONObject.NULL).put("reason","incomplete_retirement_evidence")
                .put("old_cleanup_methods_verified",false).put("direct_old_window_query_performed",false)
                .put("business_verified",false);
        try{
            String schema=text(prior,"schema");
            need(schema.equals("hepta.web-helper.lease-journal.v1")||schema.equals("hepta.web-helper.lease-journal.v2")
                    ||schema.equals("hepta.web-helper.lease-journal.v3")
                    ||schema.equals(WebEvidenceProtocol.JOURNAL_SCHEMA),"unsupported prior journal");
            need(text(prior,"state").equals("active")||text(prior,"state").equals("unknown"),"prior state is not an unresolved lease");
            JSONObject binding=prior.getJSONObject("binding");
            if(WebEvidenceProtocol.JOURNAL_SCHEMA.equals(schema))WebTaskPurpose.requireBinding(binding);
            need(WebEvidenceBinding.sha256(binding).equals(text(prior,"binding_sha256")),"prior binding hash differs");
            JSONObject bg=binding.getJSONObject("background"),helper=binding.getJSONObject("helper_identity");
            int oldBoot=integer(bg,"boot_count"),oldDisplay=integer(bg,"display_id"),oldPid=integer(prior,"helper_pid");
            int uid=integer(helper,"uid"),oldWindow=integer(prior,"window_id");
            String oldName=text(bg,"display_name"),generation=text(bg,"generation");
            need(oldBoot>=0&&oldDisplay>0&&oldPid>0&&uid>=10000&&oldWindow>=0
                    &&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(helper,"package"))
                    &&WebEvidenceProtocol.uuid(generation)&&oldName.equals("hepta-bg-"+generation)
                    &&WebEvidenceProtocol.uuid(text(prior,"webview_instance")),"prior identity incomplete");
            exact(observed,"schema","current_boot_count_before","current_boot_count_after","started_elapsed_ms","ended_elapsed_ms",
                    "current_process","active_bound_view_count","pending_capture_count","displays_before","displays_after",
                    "direct_old_display_before","direct_old_display_after","exit_records","exit_records_status","errors");
            need(observed.getJSONArray("errors").length()==0,"native probe reported an unavailable observation");
            need(PROBE_SCHEMA.equals(text(observed,"schema")),"probe schema differs");
            int boot=integer(observed,"current_boot_count_before");
            need(boot>=oldBoot&&boot==integer(observed,"current_boot_count_after"),"boot unknown, regressed or changed during probe");
            long begin=number(observed,"started_elapsed_ms"),end=number(observed,"ended_elapsed_ms");
            need(begin>0&&end>=begin&&end-begin<=MAX_PROBE_MS,"probe elapsed bracket invalid");
            JSONObject process=observed.getJSONObject("current_process");
            processShape(process);
            need(integer(process,"uid")==uid&&integer(process,"pid")>0
                    &&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(process,"process_name"))
                    &&integer(process,"boot_count")==boot&&number(process,"recorded_elapsed_ms")<=begin,"current process identity differs");
            need(integer(observed,"active_bound_view_count")==0&&integer(observed,"pending_capture_count")==0,"current owned work still exists");
            need(observed.get("direct_old_display_before")==JSONObject.NULL&&observed.get("direct_old_display_after")==JSONObject.NULL,"old display ID is still accessible");
            displaysAbsent(observed.getJSONArray("displays_before"),oldDisplay,oldName);
            displaysAbsent(observed.getJSONArray("displays_after"),oldDisplay,oldName);
            String kind;
            JSONObject exitMatch=null;
            if(boot>oldBoot){
                need("not_required_boot_changed".equals(text(observed,"exit_records_status"))
                        &&observed.getJSONArray("exit_records").length()==0,"unexpected reboot probe shape");
                kind="boot_changed";
            }else{
                JSONObject oldProcess=prior.optJSONObject("process_identity"),oldDisplayProbe=prior.optJSONObject("display_before");
                need(oldProcess!=null&&oldDisplayProbe!=null,"same_boot_requires_recorded_process_summary_and_public_display");
                processShape(oldProcess);
                exact(oldDisplayProbe,"display_id","name","flags","valid");
                need(integer(oldProcess,"pid")==oldPid&&integer(oldProcess,"uid")==uid
                        &&integer(oldProcess,"boot_count")==oldBoot
                        &&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(oldProcess,"process_name"))
                        &&Boolean.TRUE.equals(oldProcess.get("state_summary_registered")),"prior process summary was not registered");
                String summary=text(oldProcess,"state_summary_hex");
                need(summary.matches("[0-9a-f]{2,256}")&&summary.length()%2==0,"prior process summary shape");
                need(!summary.equals(text(process,"state_summary_hex")),"old and current process summary must differ");
                need(integer(oldDisplayProbe,"display_id")==oldDisplay&&oldName.equals(text(oldDisplayProbe,"name"))
                        &&Boolean.TRUE.equals(oldDisplayProbe.get("valid"))
                        &&(integer(oldDisplayProbe,"flags")&4)==0,"prior display was not observed publicly accessible");
                need("queried".equals(text(observed,"exit_records_status")),"process exit query unavailable");
                JSONArray exits=observed.getJSONArray("exit_records");need(exits.length()<=MAX_EXIT_RECORDS,"exit record budget");
                int matches=0;
                for(int i=0;i<exits.length();i++){
                    JSONObject row=exits.getJSONObject(i);
                    exact(row,"pid","real_uid","package_uid","process_name","reason","status","timestamp_ms","state_summary_hex");
                    integer(row,"reason");integer(row,"status");
                    need(integer(row,"pid")>0&&integer(row,"real_uid")>=0&&integer(row,"package_uid")>=0
                            &&text(row,"process_name").length()<=256&&number(row,"timestamp_ms")>=0,"invalid native exit record");
                    Object recordedSummary=row.get("state_summary_hex");
                    need(recordedSummary==JSONObject.NULL||(recordedSummary instanceof String
                            &&((String)recordedSummary).matches("[0-9a-f]{0,256}")&&((String)recordedSummary).length()%2==0),"invalid exit summary");
                    if(integer(row,"pid")==oldPid&&integer(row,"real_uid")==uid&&integer(row,"package_uid")==uid
                            &&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(row,"process_name"))
                            &&summary.equals(row.opt("state_summary_hex"))&&number(row,"timestamp_ms")>0){
                        matches++;exitMatch=row;
                    }
                }
                need(matches==1,"one exact native process-exit record required");
                kind="matched_process_exit";
            }
            answer.put("verified",true).put("kind",kind).put("reason","original_process_and_owned_display_no_longer_present")
                    .put("old_boot_count",oldBoot).put("current_boot_count",boot)
                    .put("old_pid",oldPid).put("old_display_id",oldDisplay).put("old_display_name",oldName).put("old_window_id",oldWindow)
                    .put("current_owned_view_absent",true).put("old_display_absent_in_accessible_scope",true)
                    .put("old_window_absence_basis",kind.equals("boot_changed")?"old_boot_ended_and_original_display_absent":"exact_original_process_exited_and_original_public_display_absent")
                    .put("matched_exit_info",exitMatch==null?JSONObject.NULL:exitMatch);
        }catch(Exception rejected){answer.put("reason",bounded(rejected.getMessage()));}
        return answer;
    }
    /**
     * Replays the complete immutable FD payload. Normal close and recovered retirement are
     * deliberately separate proof types; this never asserts that old cleanup calls ran.
     */
    public static JSONObject evaluateRecord(JSONObject record)throws Exception{
        JSONObject answer=new JSONObject().put("schema","hepta.web-helper.retirement-record-verdict.v1")
                .put("retirement_verified",false).put("reason","incomplete_recovery_record")
                .put("old_cleanup_methods_verified",false).put("business_verified",false);
        try{
            exact(record,"schema","request_json_utf8","request_sha256","binding","binding_sha256",
                    "prior_journal_utf8","prior_journal_bytes","prior_journal_sha256","preserved_prior_record",
                    "original_cleanup","actual_controller_identity","actual_helper_identity",
                    "native_probe_before","native_probe_after","storage_retirement","completed_elapsed_ms",
                    "old_cleanup_methods_verified","business_verified");
            need("hepta.web-helper.recovered-retirement.v1".equals(text(record,"schema"))
                    &&Boolean.FALSE.equals(record.get("old_cleanup_methods_verified"))
                    &&Boolean.FALSE.equals(record.get("business_verified")),"recovery record scope differs");
            String priorRaw=text(record,"prior_journal_utf8"),requestRaw=text(record,"request_json_utf8");
            byte[] priorBytes=priorRaw.getBytes(java.nio.charset.StandardCharsets.UTF_8);
            need(priorBytes.length>0&&priorBytes.length<=65536&&priorBytes.length==number(record,"prior_journal_bytes")
                    &&digest(priorBytes).equals(text(record,"prior_journal_sha256")),"original journal bytes/hash differ");
            need(digest(requestRaw.getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(text(record,"request_sha256")),"request hash differs");
            JSONObject prior=new JSONObject(priorRaw),request=new JSONObject(requestRaw);
            exact(request,"schema","request_nonce","task_id","controller_session_nonce","deadline_elapsed_ms","reason");
            String expectedCloseSchema=WebEvidenceProtocol.BINDING_SCHEMA.equals(text(prior.getJSONObject("binding"),"schema"))
                    ?WebEvidenceProtocol.requestSchema(WebEvidenceProtocol.CLOSE):"hepta.web-helper.close.v2";
            need(expectedCloseSchema.equals(text(request,"schema"))
                    &&text(request,"request_nonce").matches("[0-9a-f]{64}")
                    &&text(request,"task_id").matches("[0-9a-f]{32}")
                    &&text(request,"controller_session_nonce").matches("[0-9a-f]{64}")
                    &&Arrays.asList("normal","cancelled","error").contains(text(request,"reason")),"fresh close request shape differs");
            JSONObject binding=record.getJSONObject("binding");
            if(WebEvidenceProtocol.BINDING_SCHEMA.equals(text(binding,"schema")))WebTaskPurpose.requireBinding(binding);
            String bindingHash=WebEvidenceBinding.sha256(binding);
            need(bindingHash.equals(text(record,"binding_sha256"))&&bindingHash.equals(text(prior,"binding_sha256"))
                    &&bindingHash.equals(WebEvidenceBinding.sha256(prior.getJSONObject("binding")))
                    &&text(request,"task_id").equals(text(binding,"task_id"))
                    &&text(request,"controller_session_nonce").equals(text(binding,"controller_session_nonce")),"original task/session/binding differs");
            need(prior.has("cleanup")&&same(prior.get("cleanup"),record.get("original_cleanup")),"original cleanup facts were changed or absent");
            JSONObject preserved=record.getJSONObject("preserved_prior_record");
            exact(preserved,"name","bytes","sha256");
            need(text(preserved,"name").equals("unresolved-journal-"+text(record,"prior_journal_sha256")+".json")
                    &&number(preserved,"bytes")==priorBytes.length
                    &&text(preserved,"sha256").equals(text(record,"prior_journal_sha256")),"preserved journal reference differs");
            need(same(binding.getJSONObject("controller_identity"),record.getJSONObject("actual_controller_identity"))
                    &&same(binding.getJSONObject("helper_identity"),record.getJSONObject("actual_helper_identity")),
                    "actual installed identities differ from the recorded lease");
            JSONObject before=record.getJSONObject("native_probe_before"),after=record.getJSONObject("native_probe_after");
            JSONObject first=evaluate(prior,before),last=evaluate(prior,after);
            need(Boolean.TRUE.equals(first.get("verified"))&&Boolean.TRUE.equals(last.get("verified"))
                    &&text(first,"kind").equals(text(last,"kind"))
                    &&number(first,"current_boot_count")==number(last,"current_boot_count")
                    &&same(before.getJSONObject("current_process"),after.getJSONObject("current_process")),
                    "native process/display evidence is not stable across recovery");
            long completed=number(record,"completed_elapsed_ms"),deadline=number(request,"deadline_elapsed_ms");
            need(number(before,"ended_elapsed_ms")<=number(after,"started_elapsed_ms")
                    &&number(after,"ended_elapsed_ms")<=completed&&completed<=deadline
                    &&deadline-number(before,"started_elapsed_ms")<=10000,"recovery does not fit the one close deadline");
            JSONObject storage=record.getJSONObject("storage_retirement");
            boolean storageVerified;
            if(binding.has("storage_profile_name")){
                WebStorageEvidence.requireRetirement(binding,storage);
                need(number(before,"ended_elapsed_ms")<=number(storage,"started_elapsed_ms")
                        &&number(storage,"ended_elapsed_ms")<=number(after,"started_elapsed_ms"),
                        "storage cleanup is outside the native probe bracket");
                storageVerified=true;
            }else{
                exact(storage,"schema","kind","profile_name","clear_invoked","storage_retirement_verified");
                need("hepta.web-helper.recovery-storage-legacy.v1".equals(text(storage,"schema"))
                        &&"legacy_profile_unrecorded".equals(text(storage,"kind"))
                        &&storage.get("profile_name")==JSONObject.NULL
                        &&Boolean.FALSE.equals(storage.get("clear_invoked"))
                        &&Boolean.FALSE.equals(storage.get("storage_retirement_verified"))
                        &&"boot_changed".equals(text(first,"kind")),"legacy storage scope requires an actual reboot and remains unknown");
                storageVerified=false;
            }
            answer.put("retirement_verified",true).put("reason","old_lease_retirement_independently_replayed")
                    .put("kind",text(first,"kind")).put("binding_sha256",bindingHash)
                    .put("prior_journal_sha256",text(record,"prior_journal_sha256"))
                    .put("recorded_profile_retirement_verified",storageVerified)
                    .put("decision_before",first).put("decision_after",last);
        }catch(Exception rejected){answer.put("reason",bounded(rejected.getMessage()));}
        return answer;
    }

    /**
     * A separate proof: this authorized attachment never dispatched WebView construction,
     * profile assignment, page loading or capture. No old destroy/clear call is inferred.
     * The caller must still authenticate the Binder sender and exact FD bytes.
     */
    public static JSONObject evaluateUnstartedRecord(JSONObject record)throws Exception{
        JSONObject answer=new JSONObject().put("schema","hepta.web-helper.unstarted-retirement-verdict.v1")
                .put("retirement_verified",false).put("reason","incomplete_unstarted_record")
                .put("old_cleanup_methods_verified",false).put("storage_cleanup_called",false)
                .put("business_verified",false);
        try{
            JSONObject binding,request,initial;String kind;
            if(WebEvidenceProtocol.UNSTARTED_SCHEMA.equals(text(record,"schema"))){
                validateInitialUnstarted(record);initial=record;binding=record.getJSONObject("binding");
                request=new JSONObject(text(record,"request_json_utf8"));kind="never_started";
            }else{
                exact(record,"schema","request_json_utf8","request_sha256","binding_sha256",
                        "initial_record_utf8","initial_record_bytes","initial_record_sha256",
                        "actual_controller_identity","actual_helper_identity","current_process_identity",
                        "started_elapsed_ms","completed_elapsed_ms","active_bound_view_count","pending_capture_count",
                        "old_cleanup_methods_verified","business_verified");
                need(WebEvidenceProtocol.UNSTARTED_CONFIRMATION_SCHEMA.equals(text(record,"schema"))
                        &&Boolean.FALSE.equals(record.get("old_cleanup_methods_verified"))
                        &&Boolean.FALSE.equals(record.get("business_verified")),"unstarted confirmation scope differs");
                String original=text(record,"initial_record_utf8");
                byte[] bytes=original.getBytes(java.nio.charset.StandardCharsets.UTF_8);
                need(bytes.length>0&&bytes.length<=WebEvidenceProtocol.MAX_UNSTARTED_RECORD_BYTES
                        &&number(record,"initial_record_bytes")==bytes.length
                        &&digest(bytes).equals(text(record,"initial_record_sha256")),"initial unstarted bytes/hash differ");
                initial=new JSONObject(original);
                need(WebEvidenceProtocol.UNSTARTED_SCHEMA.equals(text(initial,"schema")),"confirmation cannot chain another confirmation");
                validateInitialUnstarted(initial);binding=initial.getJSONObject("binding");
                request=unstartedClose(record,binding);
                JSONObject firstRequest=new JSONObject(text(initial,"request_json_utf8"));
                JSONObject attach=new JSONObject(text(initial,"attach_request_json_utf8"));
                need(!text(request,"request_nonce").equals(text(firstRequest,"request_nonce"))
                        &&!text(request,"request_nonce").equals(text(attach,"request_nonce")),"confirmation nonce is not fresh");
                need(WebEvidenceBinding.sha256(binding).equals(text(record,"binding_sha256"))
                        &&same(binding.getJSONObject("controller_identity"),record.getJSONObject("actual_controller_identity"))
                        &&same(binding.getJSONObject("helper_identity"),record.getJSONObject("actual_helper_identity")),"confirmation immutable identity differs");
                JSONObject process=record.getJSONObject("current_process_identity");processShape(process);
                need(integer(process,"uid")==integer(binding.getJSONObject("helper_identity"),"uid")
                        &&integer(process,"pid")>0&&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(process,"process_name"))
                        &&integer(process,"boot_count")>=integer(binding.getJSONObject("background"),"boot_count"),
                        "confirmation current helper process differs");
                long begin=number(record,"started_elapsed_ms"),end=number(record,"completed_elapsed_ms");
                unstartedDeadline(request,begin,end);
                need(number(process,"recorded_elapsed_ms")<=begin
                        &&integer(record,"active_bound_view_count")==0&&integer(record,"pending_capture_count")==0,
                        "confirmation overlaps owned work or predates current process");
                kind="confirmed_never_started";
            }
            answer.put("retirement_verified",true).put("reason","matching_authorized_attachment_never_started_owned_web_resources")
                    .put("kind",kind).put("binding_sha256",WebEvidenceBinding.sha256(binding))
                    .put("task_id",text(binding,"task_id")).put("controller_session_nonce",text(binding,"controller_session_nonce"))
                    .put("request_nonce",text(request,"request_nonce")).put("owned_resources_never_started",true)
                    .put("prior_journal_sha256",text(initial,"prior_journal_sha256"));
        }catch(Exception rejected){answer.put("reason",bounded(rejected.getMessage()));}
        return answer;
    }
    private static void validateInitialUnstarted(JSONObject record)throws Exception{
        exact(record,"schema","request_json_utf8","request_sha256","binding","binding_sha256",
                "attach_request_json_utf8","attach_request_sha256","attach_bound_elapsed_ms",
                "prior_journal_utf8","prior_journal_bytes","prior_journal_sha256","preserved_prior_record",
                "original_cleanup","actual_controller_identity","actual_helper_identity",
                "process_identity_before","process_identity_after","resource_fence_before","resource_fence_after",
                "started_elapsed_ms","completed_elapsed_ms","old_cleanup_methods_verified","business_verified");
        need(WebEvidenceProtocol.UNSTARTED_SCHEMA.equals(text(record,"schema"))
                &&Boolean.FALSE.equals(record.get("old_cleanup_methods_verified"))
                &&Boolean.FALSE.equals(record.get("business_verified")),"initial unstarted scope differs");
        JSONObject binding=record.getJSONObject("binding"),bg=binding.getJSONObject("background");
        WebTaskPurpose.requireBinding(binding);
        String bindingHash=WebEvidenceBinding.sha256(binding);
        need(bindingHash.equals(text(record,"binding_sha256")),"unstarted binding hash differs");
        JSONObject attach=boundedObject(record,"attach_request_json_utf8","attach_request_sha256",WebEvidenceProtocol.MAX_REQUEST_BYTES);
        exactSet(attach,WebEvidenceProtocol.requestKeys(WebEvidenceProtocol.ATTACH));
        need(WebEvidenceProtocol.requestSchema(WebEvidenceProtocol.ATTACH).equals(text(attach,"schema"))
                &&WebEvidenceProtocol.hex64(text(attach,"request_nonce"))
                &&bindingHash.equals(WebEvidenceBinding.sha256(WebEvidenceBinding.fromAttach(attach))),
                "original authorized attach/binding differs");
        need(WebEvidenceProtocol.hex32(text(binding,"task_id"))&&WebEvidenceProtocol.hex64(text(binding,"controller_session_nonce"))
                &&digest(text(binding,"owner").getBytes(java.nio.charset.StandardCharsets.UTF_8)).equals(text(binding,"owner_sha256")),
                "unstarted owner/task/session shape differs");
        JSONObject helper=binding.getJSONObject("helper_identity"),controller=binding.getJSONObject("controller_identity");
        exactSet(helper,WebEvidenceProtocol.IDENTITY_KEYS);exactSet(controller,WebEvidenceProtocol.IDENTITY_KEYS);
        need(WebEvidenceProtocol.HELPER_PACKAGE.equals(text(helper,"package"))
                &&WebEvidenceProtocol.CONTROLLER_PACKAGE.equals(text(controller,"package"))
                &&number(helper,"version_code")==WebEvidenceProtocol.HELPER_VERSION_CODE
                &&integer(helper,"uid")>=10000&&integer(controller,"uid")>=10000
                &&WebEvidenceProtocol.SIGNER_SHA256.equals(text(helper,"signer_sha256"))
                &&WebEvidenceProtocol.SIGNER_SHA256.equals(text(controller,"signer_sha256"))
                &&same(helper,record.getJSONObject("actual_helper_identity"))
                &&same(controller,record.getJSONObject("actual_controller_identity")),"unstarted installed identities differ");
        JSONObject request=unstartedClose(record,binding);
        need(!text(attach,"request_nonce").equals(text(request,"request_nonce")),"close cannot reuse attach nonce");
        String priorRaw=text(record,"prior_journal_utf8");byte[] priorBytes=priorRaw.getBytes(java.nio.charset.StandardCharsets.UTF_8);
        need(priorBytes.length>0&&priorBytes.length<=65536&&priorBytes.length==number(record,"prior_journal_bytes")
                &&digest(priorBytes).equals(text(record,"prior_journal_sha256")),"original unknown journal bytes/hash differ");
        JSONObject prior=new JSONObject(priorRaw);
        need(WebEvidenceProtocol.JOURNAL_SCHEMA.equals(text(prior,"schema"))&&"unknown".equals(text(prior,"state"))
                &&bindingHash.equals(text(prior,"binding_sha256"))
                &&same(binding,prior.getJSONObject("binding"))&&number(prior,"navigation_epoch")==0
                &&text(record,"attach_request_json_utf8").equals(text(prior,"attach_request_json_utf8"))
                &&text(record,"attach_request_sha256").equals(text(prior,"attach_request_sha256"))
                &&text(record,"attach_request_sha256").equals(text(prior.getJSONObject("consumed_requests"),text(attach,"request_nonce"))),
                "original unknown journal does not bind this exact attach");
        JSONObject preserved=record.getJSONObject("preserved_prior_record");
        exact(preserved,"name","bytes","sha256");
        need(text(preserved,"name").equals("unresolved-journal-"+text(record,"prior_journal_sha256")+".json")
                &&number(preserved,"bytes")==priorBytes.length&&text(preserved,"sha256").equals(text(record,"prior_journal_sha256")),
                "unknown original was not retained by exact reference");
        JSONObject cleanup=record.getJSONObject("original_cleanup");exactSet(cleanup,WebEvidenceProtocol.CLEANUP_KEYS);
        need(same(cleanup,prior.get("cleanup"))&&Boolean.TRUE.equals(cleanup.get("active_view_absent")),"original no-resource cleanup differs");
        for(String key:WebEvidenceProtocol.CLEANUP_KEYS)if(!"active_view_absent".equals(key))
            need(Boolean.FALSE.equals(cleanup.get(key)),"unstarted record cannot assert destroy/stop/capture-retire/storage-clear calls");
        need(prior.get("storage_isolation")==JSONObject.NULL,"unstarted journal already has a profile");
        JSONObject first=record.getJSONObject("process_identity_before"),last=record.getJSONObject("process_identity_after");
        processShape(first);processShape(last);
        need(same(first,last)&&same(first,prior.getJSONObject("process_identity"))
                &&integer(first,"pid")==integer(prior,"helper_pid")&&integer(first,"pid")>0
                &&integer(first,"uid")==integer(helper,"uid")&&WebEvidenceProtocol.HELPER_PACKAGE.equals(text(first,"process_name"))
                &&integer(first,"boot_count")==integer(bg,"boot_count"),"unstarted original process identity differs");
        long begin=number(record,"started_elapsed_ms"),end=number(record,"completed_elapsed_ms"),bound=number(record,"attach_bound_elapsed_ms");
        unstartedDeadline(request,begin,end);
        need(number(first,"recorded_elapsed_ms")<=bound&&bound<=begin
                &&bound==number(prior,"attach_bound_elapsed_ms")&&number(bg,"created_elapsed_ms")<=bound
                &&bound<=number(attach,"deadline_elapsed_ms")&&number(attach,"deadline_elapsed_ms")<=number(bg,"expires_elapsed_ms"),
                "original attach time is not within its authorized lease");
        JSONObject before=record.getJSONObject("resource_fence_before"),after=record.getJSONObject("resource_fence_after");
        unstartedFence(before,binding,prior,begin,end);unstartedFence(after,binding,prior,begin,end);
        need(number(before,"observed_elapsed_ms")<=number(after,"observed_elapsed_ms")
                &&number(before,"activity_created_elapsed_ms")<=bound
                &&number(before,"activity_created_elapsed_ms")==number(after,"activity_created_elapsed_ms"),
                "unstarted UI bracket changed");
    }
    private static JSONObject boundedObject(JSONObject record,String rawKey,String hashKey,int limit)throws Exception{
        String raw=text(record,rawKey);byte[] bytes=raw.getBytes(java.nio.charset.StandardCharsets.UTF_8);
        need(bytes.length>0&&bytes.length<=limit&&digest(bytes).equals(text(record,hashKey)),"original request bytes/hash differ");
        return new JSONObject(raw);
    }
    private static JSONObject unstartedClose(JSONObject record,JSONObject binding)throws Exception{
        JSONObject request=boundedObject(record,"request_json_utf8","request_sha256",WebEvidenceProtocol.MAX_REQUEST_BYTES);
        exactSet(request,WebEvidenceProtocol.requestKeys(WebEvidenceProtocol.CLOSE));
        need(WebEvidenceProtocol.requestSchema(WebEvidenceProtocol.CLOSE).equals(text(request,"schema"))
                &&WebEvidenceProtocol.hex64(text(request,"request_nonce"))
                &&text(binding,"task_id").equals(text(request,"task_id"))
                &&text(binding,"controller_session_nonce").equals(text(request,"controller_session_nonce"))
                &&Arrays.asList("normal","cancelled","error").contains(text(request,"reason")),"matching close request required");
        return request;
    }
    private static void unstartedDeadline(JSONObject request,long begin,long end)throws Exception{
        long deadline=number(request,"deadline_elapsed_ms");
        need(begin>0&&end>=begin&&end<=deadline&&deadline-begin<=WebEvidenceProtocol.MAX_RPC_FUTURE_MS
                &&end-begin<=MAX_PROBE_MS,"unstarted evidence exceeds fresh close deadline");
    }
    private static void unstartedFence(JSONObject fence,JSONObject binding,JSONObject prior,long begin,long end)throws Exception{
        exact(fence,"schema","observed_elapsed_ms","activity_created_elapsed_ms","planned_webview_instance",
                "placeholder_window_id","owned_display_id","bound_page","retired",
                "resource_creation_dispatched","profile_assignment_dispatched","load_dispatch_count","capture_dispatch_count",
                "webview_present","capture_present","profile_present","preparing","live_webview_count","pending_capture_count");
        need(WebEvidenceProtocol.UNSTARTED_FENCE_SCHEMA.equals(text(fence,"schema"))
                &&number(fence,"observed_elapsed_ms")>=begin&&number(fence,"observed_elapsed_ms")<=end
                &&number(fence,"activity_created_elapsed_ms")>=number(binding.getJSONObject("background"),"created_elapsed_ms")
                &&text(fence,"planned_webview_instance").equals(text(prior,"webview_instance"))
                &&WebEvidenceProtocol.uuid(text(fence,"planned_webview_instance"))
                &&integer(fence,"placeholder_window_id")==integer(prior,"window_id")&&integer(prior,"window_id")>=0
                &&integer(fence,"owned_display_id")==integer(binding.getJSONObject("background"),"display_id")
                &&integer(fence,"owned_display_id")>0&&Boolean.TRUE.equals(fence.get("bound_page"))
                &&Boolean.TRUE.equals(fence.get("retired")),"unstarted placeholder/fence identity differs");
        for(String key:new String[]{"resource_creation_dispatched","profile_assignment_dispatched","webview_present","capture_present","profile_present","preparing"})
            need(Boolean.FALSE.equals(fence.get(key)),"unstarted fence includes dispatched or active resource");
        for(String key:new String[]{"load_dispatch_count","capture_dispatch_count","live_webview_count","pending_capture_count"})
            need(number(fence,key)==0,"unstarted fence includes owned work");
    }
    private static void exactSet(JSONObject value,Set<String> keys)throws Exception{
        need(value.length()==keys.size(),"unexpected exact JSON keys");
        java.util.Iterator<String> it=value.keys();while(it.hasNext())need(keys.contains(it.next()),"unexpected exact JSON key");
    }

    private static boolean same(Object a,Object b)throws Exception{
        JSONObject left=new JSONObject().put("value",a==null?JSONObject.NULL:a);
        JSONObject right=new JSONObject().put("value",b==null?JSONObject.NULL:b);
        return WebEvidenceBinding.sha256(left).equals(WebEvidenceBinding.sha256(right));
    }
    private static String digest(byte[] bytes)throws Exception{
        byte[] raw=java.security.MessageDigest.getInstance("SHA-256").digest(bytes);
        StringBuilder out=new StringBuilder();for(byte b:raw)out.append(String.format(java.util.Locale.ROOT,"%02x",b&255));
        return out.toString();
    }
    private static void processShape(JSONObject process)throws Exception{
        exact(process,"schema","pid","uid","process_name","boot_count","recorded_elapsed_ms","state_summary_hex",
                "state_summary_registered","state_summary_registration_error");
        need("hepta.web-helper.process-identity.v1".equals(text(process,"schema"))
                &&number(process,"recorded_elapsed_ms")>0,"process identity schema/time invalid");
        String token=text(process,"state_summary_hex");
        need(token.matches("[0-9a-f]{2,256}")&&token.length()%2==0,"process summary shape invalid");
        Object registered=process.get("state_summary_registered"),error=process.get("state_summary_registration_error");
        need(registered instanceof Boolean,"process summary registration must be a boolean");
        need(Boolean.TRUE.equals(registered)?error==JSONObject.NULL:error instanceof String,"process summary registration/error inconsistent");
    }
    private static void displaysAbsent(JSONArray rows,int oldId,String oldName)throws Exception{
        need(rows.length()>0&&rows.length()<=MAX_DISPLAYS,"display snapshot unavailable or over budget");
        Set<Integer> ids=new HashSet<Integer>();boolean defaultSeen=false;
        for(int i=0;i<rows.length();i++){
            JSONObject row=rows.getJSONObject(i);exact(row,"display_id","name","flags","valid");
            int id=integer(row,"display_id");String name=text(row,"name");
            need(id>=0&&ids.add(id)&&name.length()<=256&&Boolean.TRUE.equals(row.get("valid")),"display snapshot invalid");
            need(id!=oldId&&!oldName.equals(name),"old display ID/name is still present");
            if(id==0)defaultSeen=true;
        }
        need(defaultSeen,"working physical-display enumeration required");
    }
    private static void exact(JSONObject o,String... fields)throws Exception{
        Set<String> wanted=new HashSet<String>(Arrays.asList(fields));need(o.length()==wanted.size(),"unexpected record fields");
        java.util.Iterator<String> keys=o.keys();while(keys.hasNext())need(wanted.contains(keys.next()),"unknown record field");
